insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1', 'RC-001', '1', 'Founder-Centric Thinking', 'Psychological', 'The founder assumes that because they personally experience a problem, many others must too. Personal frustration is mistaken for market demand without any external verification.', '0.68', 'external', '2026-07-10 14:07:52.02522+00', '2026-08-03 03:11:30.246727+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('2', 'RC-002', '1', 'Solution Attachment', 'Psychological', 'The founder falls in love with the solution before proving the problem exists at scale. Emotional investment makes objective validation feel threatening.', '0.68', 'external', '2026-07-10 14:07:52.02522+00', '2026-08-03 03:11:45.207588+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('3', 'RC-003', '1', 'Lack of Customer Discovery', 'Knowledge', 'Few or no customer interviews are conducted before building begins. All product decisions rest on internal assumptions rather than external evidence.', '0.72', 'external', '2026-07-10 14:07:52.02522+00', '2026-08-03 03:11:45.263895+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('4', 'RC-004', '1', 'Confirmation Bias', 'Psychological', 'The founder seeks feedback only from people likely to support the idea. Contradictory signals are unconsciously filtered out or rationalized away.', '0.68', 'external', '2026-07-10 14:07:52.02522+00', '2026-08-03 03:11:45.313913+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('5', 'RC-005', '1', 'Fear of Negative Feedback', 'Psychological', 'Validation is avoided because the founder fears hearing the idea is weak. Building feels productive and safe; testing feels risky and exposing.', '0.68', 'external', '2026-07-10 14:07:52.02522+00', '2026-08-03 03:11:30.523872+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
