insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('650', 'RC-650', '101', 'Hero Syndrome', 'Psychological', 'The belief that everything depends on the founder creates total responsibility without relief.', '0.72', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.435508+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('651', 'RC-651', '101', 'Lack of Boundaries', 'Knowledge', 'Work expands to fill all available time because no limits have been established or enforced.', '0.72', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.286431+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('652', 'RC-652', '101', 'Poor Delegation', 'Behavioural', 'Responsibility and workload accumulate because ownership is never transferred to the team.', '0.65', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.336204+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('653', 'RC-653', '101', 'Perfectionism', 'Psychological', 'Rest feels undeserved because the standard of done is never reached.', '0.72', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.384421+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('654', 'RC-654', '101', 'Financial Stress', 'Operational', 'Constant economic pressure creates a sustained state of anxiety that depletes resources over time.', '0.75', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.638676+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('655', 'RC-655', '101', 'Isolation', 'Psychological', 'The gradual weakening of support systems removes the social and emotional resources needed for recovery.', '0.72', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:40.246867+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('656', 'RC-656', '101', 'Sleep Deprivation', 'Psychological', 'Chronic inadequate sleep progressively degrades cognitive performance, emotional regulation, and resilience.', '0.72', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:40.294673+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('657', 'RC-657', '101', 'Emotional Suppression', 'Psychological', 'Stress, anxiety, and difficult emotions are consistently suppressed rather than processed, causing accumulation.', '0.72', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.481343+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('658', 'RC-658', '101', 'Mission Obsession', 'Psychological', 'The founder cannot psychologically disconnect from the company, making genuine recovery impossible.', '0.72', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.687114+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('659', 'RC-659', '101', 'Lack of Self-Awareness', 'Psychological', 'Warning signs — irritability, declining quality, loss of enthusiasm — are ignored until collapse occurs.', '0.72', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.532168+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('660', 'RC-660', '101', 'Unsustainable Ambition', 'Behavioural', 'Growth goals consistently exceed what the founder current capacity can realistically support.', '0.65', 'internal', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.57746+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('661', 'RC-661', '46', 'Informal Systems Not Designed for Scale', 'Operational', 'The organisation relies on informal coordination that worked when the team was small but breaks down completely as headcount grows. No formal decision frameworks or ownership structures were ever designed.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.713257+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('662', 'RC-662', '46', 'No Defined Decision Rights Framework', 'Strategic', 'Authority and decision ownership were never formally documented. As more people join, it becomes unclear who has final say on what, creating delays and conflicts.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.064075+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('663', 'RC-663', '46', 'Processes Not Documented Before Scaling', 'Operational', 'Core processes existed only in people heads and were never written down before the team grew. New employees have no reference point and make inconsistent decisions.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.210987+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('664', 'RC-664', '47', 'Volume Exceeds Manual Capacity', 'Operational', 'Processes that worked when handled manually by one or two people collapse when volume increases. No automation or systems were built to handle scale.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.271233+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('665', 'RC-665', '47', 'No Early Warning Systems Built', 'Operational', 'The team has no metrics or alerts that signal when a process is under stress. Problems are only discovered after they have already caused visible damage.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.376947+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('666', 'RC-666', '47', 'Founder Removal Exposed Process Fragility', 'Behavioural', 'Processes only worked because the founder was personally managing them. When they stepped back, the process failed — revealing it was never really a process, just founder oversight.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.572732+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('667', 'RC-667', '48', 'Documentation Treated as Low Priority', 'Behavioural', 'Founders and early team members view documentation as bureaucratic overhead. Knowledge stays in people heads because writing it down never feels urgent until someone leaves.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.76418+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('668', 'RC-668', '48', 'No Knowledge Management System Implemented', 'Operational', 'No tool or process was established for capturing and sharing institutional knowledge. When people leave, their knowledge leaves with them.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.216686+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('669', 'RC-669', '48', 'Speed Culture Discourages Documentation', 'Behavioural', 'The team moves so fast that pausing to document feels like slowing down. A culture of speed without structure means the same problems are solved repeatedly from scratch.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.41053+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('670', 'RC-670', '49', 'Delegation Discomfort', 'Psychological', 'The founder is psychologically uncomfortable handing over control. Involvement feels like quality assurance — but it actually prevents the team from developing independence.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.320249+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('671', 'RC-671', '49', 'No Decision Authority Distributed to Team', 'Operational', 'The founder never formally established which decisions managers can make independently. Everything defaults to the founder because no alternative was ever made official.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.426013+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('672', 'RC-672', '49', 'Trust Gap with New Team Members', 'Psychological', 'The founder does not yet trust the expanded team to make decisions at the standard they would. This is sometimes valid early on but becomes a structural problem when it persists.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.474967+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('673', 'RC-673', '50', 'No Cross-Functional Coordination Mechanism', 'Operational', 'No regular cross-team meeting, shared dashboard, or coordination process was established. Teams optimise locally without visibility into what others are doing.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.571805+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('674', 'RC-674', '50', 'Teams Using Incompatible Tools and Systems', 'Operational', 'Different departments adopted different tools independently. Without integration, information cannot flow between teams and visibility is fragmented.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.622875+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('675', 'RC-675', '50', 'Growth Created Departmental Identity Before Shared Identity', 'Behavioural', 'As the company grew, department loyalty developed faster than company-wide identity. Teams began protecting their own turf rather than collaborating toward shared goals.', '0.70', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.595364+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('676', 'RC-676', '51', 'No Formal Internal Communication Cadence', 'Operational', 'No structured cadence — all-hands, team updates, manager check-ins — was established as the team grew. Information sharing remained informal and inconsistent.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.456884+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('677', 'RC-677', '51', 'Reliance on Chat Messages for Critical Information', 'Behavioural', 'Important decisions and updates are communicated through informal chat channels where they get buried. No system for separating signal from noise was ever built.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.20286+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('678', 'RC-678', '51', 'Founder Assumption That Team Has Same Context', 'Psychological', 'The founder assumes team members have context that was never explicitly shared. What is obvious to the founder is invisible to team members who were not in early conversations.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:45.10512+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('679', 'RC-679', '52', 'No Structured Onboarding Programme Built', 'Operational', 'Onboarding was never designed as a system. New hires learn from whoever has time — creating inconsistent understanding of how the company actually works.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.524958+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('680', 'RC-680', '52', 'Onboarding Deprioritised During Growth', 'Behavioural', 'When the company is growing fast, onboarding gets squeezed out by operational urgency. The cost of poor onboarding — slow ramp, inconsistent quality — compounds over time.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.503369+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('681', 'RC-681', '52', 'No Role-Specific Onboarding Materials', 'Operational', 'Generic onboarding materials exist but role-specific knowledge transfer was never built. Each new hire figures out their specific job largely on their own.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.671901+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('682', 'RC-682', '53', 'No Formal Quality Management System', 'Operational', 'Quality was maintained by founder oversight when the team was small. No formal QA process, standards, or review mechanism was built before the founder stepped back.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.62285+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('683', 'RC-683', '53', 'Standards Implicit Rather Than Documented', 'Knowledge', 'What constitutes good quality exists only in the founder head. Without documented standards, team members work to different definitions of acceptable output.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.641554+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('684', 'RC-684', '53', 'Insufficient QA Resources for Increased Volume', 'Operational', 'Quality checking resources did not scale with output volume. The same number of people checking a much larger amount of work means more errors slip through.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.775026+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('685', 'RC-685', '54', 'Management Roles Defined Without Clarity on Authority', 'Strategic', 'Manager roles were created but the boundaries of their decision-making authority were never explicitly defined. Managers do not know what they can decide independently.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.809314+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('686', 'RC-686', '54', 'Founder Overriding Managers Publicly', 'Behavioural', 'The founder regularly overrides manager decisions in front of the team. This undermines manager credibility and teaches the team to escalate everything to the founder.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.686896+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('687', 'RC-687', '54', 'No Management Training or Development Programme', 'Knowledge', 'Newly promoted managers have no training for their new role. They were excellent individual contributors but managing people is a different skill that was never developed.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.720181+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('688', 'RC-688', '55', 'Too Many People Required to Make Routine Decisions', 'Operational', 'Decision processes that required one person now require multiple stakeholders. No work was done to define which decisions are routine and can be made quickly by one person.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.550156+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('689', 'RC-689', '55', 'Risk Aversion Increasing as Company Grows', 'Psychological', 'As more is at stake, managers become more conservative and escalate more decisions upward. A culture of caution replaces the startup original bias toward speed.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.876795+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('690', 'RC-690', '55', 'No Decision-Making Framework or Principles Defined', 'Strategic', 'No documented principles exist for how decisions should be made at different levels. Without this, every decision gets made differently depending on who is involved.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.82427+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('691', 'RC-691', '56', 'Identity Tied to Hands-On Contribution', 'Psychological', 'The founder sense of value and contribution is tied to doing work rather than enabling others. Stepping back from execution feels like becoming less important.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.735038+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('692', 'RC-692', '56', 'Lack of Trust in Team Capability', 'Psychological', 'Deep down the founder does not believe the team can do the work to the required standard without their involvement. This belief — often unconscious — prevents real delegation.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:20.176531+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('693', 'RC-693', '56', 'No Transition Plan from Operator to Leader', 'Strategic', 'No deliberate plan was made for how the founder would shift from doing to leading. The transition was assumed to happen naturally rather than being designed.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:26.969504+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('694', 'RC-694', '57', 'No Unified Financial Reporting Across Streams', 'Operational', 'Financial systems were built for one revenue model and were never restructured as new streams were added. Consolidated reporting requires manual work to produce.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:44.751356+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('695', 'RC-695', '57', 'Different Billing Systems Not Integrated', 'Operational', 'Separate billing systems for different revenue streams create reconciliation challenges, payment timing mismatches, and visibility gaps.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:29.872336+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('696', 'RC-696', '57', 'Revenue Model Complexity Added Without Finance Infrastructure', 'Strategic', 'New revenue streams were launched without building the financial management infrastructure to support them. Growth outpaced the company financial operational capability.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:44.802109+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('697', 'RC-697', '58', 'No Formal Pricing Strategy for Different Customer Segments', 'Strategic', 'Pricing was set for one customer type and never updated as the company began serving enterprises, SMBs, and different verticals with very different willingness to pay.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:29.687195+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('698', 'RC-698', '58', 'Sales Team Empowered to Discount Without Framework', 'Operational', 'No formal discount policy exists. Salespeople use their own judgment on pricing, creating wide variance in deal terms and eroding pricing integrity.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:45.003584+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('699', 'RC-699', '58', 'Original Pricing Set Without Segmentation Analysis', 'Knowledge', 'The pricing model was designed when the founder had limited understanding of different customer segments. It was never revisited as segment clarity improved.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:45.053519+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('700', 'RC-700', '59', 'No Renewal Tracking System Built', 'Operational', 'Subscription renewals are not tracked proactively. The team discovers churn only after it happens rather than managing accounts toward renewal.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:09.679404+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('701', 'RC-701', '59', 'No Customer Health Scoring System', 'Operational', 'No system exists to identify which customers are at risk before they cancel. Without leading indicators, the team cannot intervene before it is too late.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.782391+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('702', 'RC-702', '59', 'Customer Success Not Treated as a Revenue Function', 'Strategic', 'Customer success is seen as a support function rather than a revenue function. The connection between retention work and revenue impact is not tracked.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.925022+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('703', 'RC-703', '60', 'Incentives Aligned Entirely to New Customer Acquisition', 'Operational', 'Sales compensation, marketing budgets, and leadership attention are all focused on acquiring new customers. Retention receives minimal resource allocation.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:14.973803+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('704', 'RC-704', '60', 'Retention Metrics Not Tracked or Reported', 'Operational', 'NRR, churn rate, and expansion revenue are not measured or reported alongside acquisition metrics. What is not measured does not get managed.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.072216+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('705', 'RC-705', '60', 'Customer Success Team Underfunded Relative to Sales', 'Strategic', 'The investment in post-sale customer success is a fraction of pre-sale sales and marketing. This structural imbalance makes churn mathematically inevitable at scale.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.972368+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('706', 'RC-706', '61', 'Pipeline Tracking Not Disciplined Enough for Forecasting', 'Operational', 'Sales pipeline data is incomplete, inconsistently updated, and insufficiently detailed to produce reliable revenue forecasts.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.019508+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('707', 'RC-707', '61', 'Sales Cycle Lengthening as Enterprise Mix Increases', 'Strategic', 'As the customer base shifts toward enterprise, sales cycles lengthen significantly. Forecasting models built on SMB cycle times are no longer accurate.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.82971+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('708', 'RC-708', '61', 'Optimism Bias in Sales Team Reporting', 'Psychological', 'Salespeople consistently overestimate deal probability and close timing. Without a disciplined review process that adjusts for this, forecasts are systematically inflated.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.855082+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('709', 'RC-709', '62', 'No Budget Approval Process as Company Scaled', 'Operational', 'Spending authority was never formally limited as the team grew. Team members continue to spend at the discretion they had when the company was smaller.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.122697+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('710', 'RC-710', '62', 'Finance Function Not Scaled with Company', 'Operational', 'The finance team remained small while the company grew, leaving insufficient capacity to monitor, forecast, and control spending across a larger organisation.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.023783+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('711', 'RC-711', '62', 'Growth Pressure Overriding Financial Discipline', 'Behavioural', 'Pressure to hit growth targets creates a culture where spending is justified by growth intent rather than measured against financial capacity or plan.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.172889+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('712', 'RC-712', '63', 'Payment Terms Extended to Win Enterprise Deals', 'Strategic', 'Enterprise customers demand longer payment terms as a condition of signing. The founder agrees to win the deal without fully modelling the working capital impact.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.267726+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('713', 'RC-713', '63', 'Inventory Levels Not Optimised for Cash Efficiency', 'Operational', 'For product businesses, inventory is ordered well in advance of need, trapping cash. No inventory optimisation system was built to reduce working capital requirements.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.068774+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('714', 'RC-714', '63', 'Cash Flow Not Modelled Separately from P and L', 'Knowledge', 'The founder monitors P and L profitability but does not model cash flow separately. A profitable business on paper can run out of cash due to timing differences.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.116192+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('715', 'RC-715', '64', 'Cost to Serve Enterprise Customers Not Modelled', 'Knowledge', 'The incremental cost of serving large enterprise customers — more support, more customisation, more compliance — was never calculated. Margins erode invisibly.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.877017+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('716', 'RC-716', '64', 'No Gross Margin Tracking by Customer Segment', 'Operational', 'Overall gross margin is tracked but not broken down by customer type, product line, or channel. Margin erosion in specific segments is invisible until it affects the total.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.914114+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('717', 'RC-717', '64', 'Operational Costs Scaling Faster Than Revenue', 'Operational', 'As the company grows, operational costs — headcount, tools, infrastructure — are growing faster than revenue. No process exists to regularly benchmark this ratio.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.220006+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('718', 'RC-718', '65', 'Sales Compensation Not Aligned with Business Priorities', 'Strategic', 'Commission structures reward behaviours — volume, new logos — that are not aligned with what the business actually needs — margin, retention, strategic accounts.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.317485+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('719', 'RC-719', '65', 'Commission Plan Too Complex to Be Motivating', 'Operational', 'The compensation plan has too many variables and exceptions. Sales reps cannot quickly calculate their own earnings, reducing the motivational effect of the incentive.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:20.690576+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('720', 'RC-720', '65', 'No Regular Review of Commission Structure Effectiveness', 'Operational', 'The sales compensation plan was set once and never formally reviewed. As the business model evolved, the incentives became increasingly misaligned.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:27.177006+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('721', 'RC-721', '66', 'Revenue Recognition Not Reviewed as Model Scaled', 'Knowledge', 'The accounting treatment of revenue was appropriate for the original business model but was never revisited as new revenue streams, contract structures, and geographies were added.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.365485+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('722', 'RC-722', '66', 'No Finance System to Handle Multi-Stream Revenue Correctly', 'Operational', 'The accounting and billing system was built for one revenue type and cannot correctly handle deferred revenue, multi-year contracts, or usage-based billing.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.210818+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('723', 'RC-723', '66', 'Finance Team Skill Gap in Complex Revenue Accounting', 'Knowledge', 'The founding finance team has strong bookkeeping skills but lacks expertise in complex revenue recognition standards required at this stage.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.163336+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('724', 'RC-724', '67', 'Churn Measured at User Level Not Revenue Level', 'Operational', 'Churn is reported as a percentage of users or accounts rather than revenue. This masks the disproportionate financial impact of losing high-value customers.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.354559+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('725', 'RC-725', '67', 'No Early Warning System for At-Risk Accounts', 'Operational', 'Without customer health scoring or proactive outreach, churn is only discovered at renewal — when it is already too late to save the account.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.924611+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('726', 'RC-726', '67', 'LTV Calculations Not Updated to Reflect Declining Tenure', 'Knowledge', 'LTV models were built on early customer cohort data when retention was higher. As churn increases, LTV projections overestimate customer lifetime and unit economics appear healthier than they are.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.257644+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('727', 'RC-727', '68', 'Financial Planning Done in Spreadsheets Without Scenario Modelling', 'Operational', 'Financial plans are built in static spreadsheets with no ability to quickly model different scenarios. Decisions are made without understanding their sensitivity to assumptions.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.42336+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('728', 'RC-728', '68', 'No Rolling Forecast Updated Monthly', 'Operational', 'Financial forecasts are produced annually and rarely updated. The plan becomes disconnected from reality within weeks of being created.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.469484+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('729', 'RC-729', '68', 'Finance and Operations Not Connected in Planning Process', 'Strategic', 'Financial planning happens separately from operational planning. Resource allocation decisions are not grounded in financial model outputs.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:40.340951+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('730', 'RC-730', '69', 'Founder Has Not Developed Manager Coaching Skills', 'Knowledge', 'Leading through managers requires different skills than direct leadership. The founder never developed the ability to coach, develop, and hold managers accountable.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.408118+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('731', 'RC-731', '69', 'Manager Expectations Not Explicitly Set', 'Operational', 'What managers are expected to own, decide, and deliver was never formally communicated. Ambiguity causes managers to underdelegate upward and second-guess their authority.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.517785+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('732', 'RC-732', '69', 'Founder Bypasses Managers During Stressful Periods', 'Behavioural', 'Under pressure, the founder reverts to direct contact with individual contributors. This undermines the management layer and signals that managers authority is conditional.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.565684+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('733', 'RC-733', '70', 'No Formal Review Process Designed as Team Grew', 'Operational', 'Performance reviews never became a formal system. Feedback is given informally, inconsistently, and usually only when a problem is already serious.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.962326+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('734', 'RC-734', '70', 'Founder Uncomfortable with Difficult Feedback Conversations', 'Psychological', 'Giving negative feedback feels confrontational and relationship-damaging. Founders avoid it, which causes underperformance to persist unchecked.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.620799+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('735', 'RC-735', '70', 'No Clear Performance Standards Defined for Roles', 'Knowledge', 'Without documented performance expectations, team members do not know what excellent looks like. Reviews become subjective and feel unfair.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.305181+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('736', 'RC-736', '71', 'Succession Planning Feels Premature to the Founder', 'Psychological', 'Planning for someone else to fill a role feels like admitting vulnerability or planning for failure. Founders delay it indefinitely.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.456207+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('737', 'RC-737', '71', 'Critical Knowledge Not Documented or Transferred', 'Operational', 'Key institutional knowledge — relationships, processes, context — exists only in the heads of a few individuals. No systematic knowledge transfer has occurred.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.502183+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('738', 'RC-738', '71', 'No Internal Talent Development Pipeline', 'Strategic', 'The company has not invested in developing internal candidates for senior roles. When a senior person leaves, there is no one ready to step into the gap.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.675648+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('739', 'RC-739', '72', 'No Compensation Benchmarking Process Established', 'Knowledge', 'Salaries are set based on negotiation and intuition rather than market data. This creates pay inequity that only becomes visible when someone compares notes.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.76978+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('740', 'RC-740', '72', 'Equity Pool Not Planned for Growth Stage Hiring Needs', 'Strategic', 'The option pool was sized for early team members and is now insufficient to offer meaningful equity to senior hires who expect market-rate grants.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.722659+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('741', 'RC-741', '72', 'Vesting Schedules Inconsistent Across Team', 'Operational', 'Different vesting terms were agreed at different times without a consistent framework. This creates resentment when team members compare arrangements.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.818024+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('742', 'RC-742', '73', 'Culture Left to Emerge Rather Than Intentionally Built', 'Behavioural', 'Culture was never deliberately designed. It emerged from early team dynamics and the founder personal style. As the team grew, the founder influence diluted and no designed culture filled the gap.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.558244+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('743', 'RC-743', '73', 'Values Documented but Not Reinforced in Decisions', 'Behavioural', 'Company values exist on paper but are not used as decision criteria in hiring, performance management, or promotions. Values become decoration rather than direction.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.605808+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('744', 'RC-744', '73', 'Cultural Norms Not Transferred During Onboarding', 'Operational', 'New hires join with no explicit communication about the company cultural norms. They pick up whatever behaviour is modelled around them — which varies by team.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.009473+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('745', 'RC-745', '74', 'No Employee Feedback Mechanisms Built', 'Operational', 'No regular structured way for employees to share how they are feeling about the company exists. Morale problems build invisibly until they cause attrition.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.74671+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('746', 'RC-746', '74', 'Communication of Company Direction and Progress Insufficient', 'Operational', 'Team members do not know how the company is performing, where it is heading, or how their work contributes. Disconnection from purpose reduces engagement.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.870704+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('747', 'RC-747', '74', 'High Growth Pace Creating Chronic Overwork', 'Behavioural', 'The company is growing fast and the team is stretched. Sustained overwork without recognition or relief reduces motivation and increases burnout risk.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.981421+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('748', 'RC-748', '75', 'Resource Scarcity Creating Zero-Sum Team Competition', 'Strategic', 'As teams compete for limited budget and headcount, collaboration becomes a threat to local interests. Teams start hoarding information and blocking each other.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:15.931681+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('749', 'RC-749', '75', 'No Clear Decision Process for Cross-Team Conflicts', 'Operational', 'When teams disagree, there is no established process for resolution. Conflicts get escalated to the founder or resolved informally through whoever has more political influence.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:27.367208+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('750', 'RC-750', '75', 'Unclear Metrics Create Competition Over Credit', 'Operational', 'Without clear team-level metrics, success is ambiguous and contested. Teams compete for credit when things go well and deflect blame when things go badly.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:20.830732+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('751', 'RC-751', '76', 'Promoted Without Management Skill Development', 'Knowledge', 'Individual contributors are promoted into management based on technical performance without any training in people leadership, coaching, or feedback skills.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.653106+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('752', 'RC-752', '76', 'No Manager Support Structure After Promotion', 'Operational', 'After being promoted, new managers receive no coaching, peer support, or structured feedback on their leadership performance. They succeed or fail entirely on their own.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.029852+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('753', 'RC-753', '76', 'Expectations of New Manager Role Not Clearly Defined', 'Operational', 'What a manager is expected to do differently from an individual contributor is never explicitly communicated. New managers default to doing their old job plus some administrative tasks.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.41085+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('754', 'RC-754', '77', 'Roles Not Redefined as Company Structure Evolved', 'Operational', 'Job descriptions and role boundaries were set during an earlier stage and never updated. As the organisation grew, responsibilities overlapped and gaps appeared.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:32.699755+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('755', 'RC-755', '77', 'No Career Progression Framework Communicated', 'Strategic', 'Team members have no visibility into how they advance in the organisation. Without a clear path forward, high performers explore opportunities elsewhere.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.076528+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('756', 'RC-756', '77', 'Fast Growth Outpaced Role Clarity', 'Operational', 'The company grew so quickly that roles were created reactively to fill immediate needs rather than designed as part of a coherent organisational structure.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.456481+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('757', 'RC-757', '78', 'No Systematic Employee Sentiment Measurement', 'Operational', 'No pulse surveys, engagement scores, or structured feedback mechanisms exist. The founder relies on intuition and informal conversations to assess culture health.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.123269+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('758', 'RC-758', '78', 'Early Warning Signals for Morale Problems Not Tracked', 'Operational', 'Metrics that predict engagement decline — absenteeism, meeting participation, voluntary attrition — are not tracked. Problems only become visible after damage is done.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:16.560228+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('759', 'RC-759', '78', 'Leadership Overconfident in Culture Health Without Data', 'Psychological', 'The founder and leadership team believe the culture is healthy because they do not hear otherwise. The absence of complaints is mistaken for evidence of engagement.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.057724+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('760', 'RC-760', '79', 'No Defensible Competitive Moat Built', 'Strategic', 'The company grew on the strength of being first but never built lasting competitive advantages — switching costs, proprietary data, network effects, brand — that would protect position.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.547882+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('761', 'RC-761', '79', 'Market Validation Attracted Well-Funded Imitators', 'Strategic', 'Proving the concept made the opportunity visible to larger, better-resourced competitors. The founder did not anticipate how quickly success would attract competition.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.502111+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('762', 'RC-762', '79', 'Competitive Intelligence Not Monitored Systematically', 'Operational', 'No process exists for tracking competitor moves, pricing changes, or new entrants. Competitive threats are discovered reactively rather than anticipated.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:16.609792+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('763', 'RC-763', '80', 'Advantage Built on Features That Are Now Standard', 'Strategic', 'The original differentiation was feature-based. Competitors have caught up and the features that were unique are now table stakes across the category.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:16.657232+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('764', 'RC-764', '80', 'No Investment in Next-Generation Competitive Advantage', 'Strategic', 'While defending the current position, no resources have been allocated to building the next source of differentiation. The company is in maintenance mode on its moat.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:27.764215+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('765', 'RC-765', '80', 'Brand and Relationships Not Leveraged as Defence', 'Strategic', 'The company has built customer relationships and brand equity that could be defensible advantages but these have not been intentionally developed as competitive barriers.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.171293+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('766', 'RC-766', '81', 'Product and Support Not Built for Enterprise Requirements', 'Operational', 'The product was designed for early adopter users who had high tolerance for gaps. Enterprise buyers require SLAs, security certifications, and support standards that were never built.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.751468+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('767', 'RC-767', '81', 'Customer Success Capacity Not Scaled for Enterprise Demands', 'Operational', 'As more enterprise customers are acquired, the support and success burden increases significantly. The customer success team was not scaled to meet these demands.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.599978+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('768', 'RC-768', '81', 'Pricing Not Adjusted for Higher Enterprise Cost to Serve', 'Strategic', 'Enterprise customers require significantly more resources to serve but pricing reflects the original SMB model. Margins deteriorate without a visible mechanism.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.64562+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('769', 'RC-769', '82', 'No Premium Positioning or Brand Differentiation Developed', 'Strategic', 'The company competed on price and features rather than investing in brand, expertise positioning, or community that could justify premium pricing as the market matured.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.220388+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('770', 'RC-770', '82', 'Category Matured Faster Than Differentiation Was Built', 'Strategic', 'The speed of market maturation exceeded the company ability to build defensible differentiation. What worked in an emerging market does not work in a mature one.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.321704+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('771', 'RC-771', '82', 'Race to Bottom on Pricing to Maintain Volume', 'Behavioural', 'In response to competitive pressure, the company reduced prices to protect volume. This accelerated margin erosion and signalled commodity status to the market.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.268921+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('772', 'RC-772', '83', 'Resources Spread Across Too Many Initiatives', 'Strategic', 'The company is pursuing too many strategic bets simultaneously. Resources are too thin to execute any single initiative to full potential.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.370111+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('773', 'RC-773', '83', 'Innovation Work Not Connected to Clear Strategic Rationale', 'Strategic', 'New product initiatives are launched without a clear theory of why this is the right time and how it connects to the core business strategy.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.116723+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('774', 'RC-774', '83', 'Core Business Quality Suffering While Attention Goes to New Products', 'Operational', 'The existing product base is stagnating as leadership attention moves to new initiatives. Core customer satisfaction is declining without being noticed.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.798258+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('775', 'RC-775', '84', 'Over-Reliance on Single Distribution Platform', 'Strategic', 'The majority of customer acquisition flows through one platform — an app store, a marketplace, a social network — creating existential dependency on one party decisions.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.706296+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('776', 'RC-776', '84', 'Platform Risk Not Assessed or Mitigated', 'Strategic', 'The risk of platform policy changes, algorithm updates, or fee increases was never formally assessed or built into business continuity planning.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.169647+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('777', 'RC-777', '84', 'No Alternative Distribution Channel Developed', 'Operational', 'Despite the concentration risk, no serious investment was made in building alternative channels that could sustain the business if the primary platform became unavailable.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.416943+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('778', 'RC-778', '85', 'No Formal Customer Loyalty or Retention Programme', 'Operational', 'No structured programme exists to reward and deepen relationships with long-term customers. Loyalty is assumed rather than designed.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.512314+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('779', 'RC-779', '85', 'Long-Term Customer Neglect as Attention Goes to New Acquisition', 'Behavioural', 'The team celebrates new customer wins while long-term customers receive declining attention. Tenure and loyalty are not recognised or reinforced.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:45.153983+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('780', 'RC-780', '85', 'No Proactive Account Management for Mature Customers', 'Operational', 'Customer relationships are managed reactively — the team responds to requests but does not proactively add value, share insights, or deepen the relationship.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:30.429299+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('781', 'RC-781', '86', 'Partnership Critical to Revenue but No Formal Agreement', 'Strategic', 'A key partner relationship drives significant revenue but operates without a formal contract defining commitments, exclusivity, or notice periods.', '0.82', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.562084+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('782', 'RC-782', '86', 'No Alternative Go-to-Market Developed Alongside Key Partnership', 'Strategic', 'The partnership became the default GTM motion. No parallel channel was developed, making the business critically dependent on the partner continued cooperation.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.464292+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('783', 'RC-783', '86', 'Partner Relationship Managed Informally Without Review Cadence', 'Operational', 'The partnership has no formal review cadence, performance metrics, or governance structure. Misalignment builds undetected until a crisis surfaces.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.892044+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('784', 'RC-784', '87', 'Local Market Regulatory Requirements Underestimated', 'Knowledge', 'Compliance requirements in the new market were assessed superficially before entry. Legal, tax, data, and employment obligations differ significantly from the home market.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.84539+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('785', 'RC-785', '87', 'Product Not Localised for New Market Requirements', 'Operational', 'The product was launched in new markets without meaningful localisation — language, payment methods, local integrations, cultural adjustments. Adoption fails as a result.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.938998+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('786', 'RC-786', '87', 'Management Bandwidth Split Across Too Many Geographies', 'Strategic', 'Senior leadership attention is divided across multiple international markets simultaneously. The home market suffers and no single international market receives sufficient focus.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:35.122609+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('787', 'RC-787', '88', 'Value Identity Tied to Technical or Operational Contribution', 'Psychological', 'The founder self-worth is derived from the work they produce — writing code, closing deals, designing features. Shifting to leadership feels like becoming less valuable.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.6101+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('788', 'RC-788', '88', 'No Role Model or Blueprint for the Transition', 'Knowledge', 'The founder has never seen or learned how to make the shift from operator to CEO. They have no framework for what their new role should look like.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.659673+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('789', 'RC-789', '88', 'Immediate Gratification of Doing vs Delayed Returns of Leading', 'Psychological', 'Execution produces immediate, visible results. Leadership produces results months later through others. The gratification gap makes doing feel more productive even when it is not.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.262101+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('790', 'RC-790', '89', 'Past Delegation Failures Reinforced Trust Deficit', 'Psychological', 'Previous experiences where delegated work went wrong reinforced the belief that the founder must do things themselves. Each failure makes the next delegation attempt less likely.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.707606+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('791', 'RC-791', '89', 'Standard Never Made Explicit Before Delegation', 'Operational', 'The founder delegates but never clearly communicates the standard they expect. When the output does not match their internal standard, they conclude delegation failed — rather than that communication failed.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:34.983186+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('792', 'RC-792', '89', 'Fear of Losing Relevance Through Delegation', 'Psychological', 'Unconsciously, the founder fears that if the team succeeds without their direct involvement, they become redundant. Staying involved protects their sense of necessity.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:35.034401+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('793', 'RC-793', '90', 'No Prior Experience Managing People More Senior', 'Knowledge', 'The founder has only managed people junior to themselves. Managing experienced executives requires different skills — listening, challenging, creating space — that were never developed.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:35.169211+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('794', 'RC-794', '90', 'Executive Autonomy Not Clearly Defined Upfront', 'Operational', 'The extent of an executive independent authority was never explicitly agreed. Both parties operate on different assumptions, creating friction when decisions are made.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:28.153674+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('795', 'RC-795', '90', 'Founder Reverting to Execution in Executive Domain', 'Behavioural', 'Under pressure, the founder takes back executive-level tasks rather than coaching the executive through the challenge. This undermines the executive and prevents their development.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:35.078416+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('796', 'RC-796', '91', 'No Experience Preparing for or Running Board Meetings', 'Knowledge', 'The founder has never operated with a formal board. The discipline of board pack preparation, structured reporting, and governance communication is entirely new.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.756487+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('797', 'RC-797', '91', 'Difficult Information Withheld from Board', 'Psychological', 'The founder feels pressure to present positively to the board. Bad news is minimised or withheld, depriving the board of the context they need to provide useful guidance.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.853762+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('798', 'RC-798', '91', 'Board Relationship Treated as Adversarial Rather Than Advisory', 'Psychological', 'The founder experiences board oversight as threatening rather than supportive. This adversarial dynamic prevents the relationship from becoming genuinely useful.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.309196+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('799', 'RC-799', '92', 'No Structured Investor Communication Cadence', 'Operational', 'Investor updates are sent ad-hoc, usually after positive events. No consistent cadence of proactive communication was established, creating anxiety when updates stop.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.90098+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('800', 'RC-800', '92', 'Information Asymmetry Between Founder and Investors', 'Operational', 'Investors lack the operational context to interpret events accurately. Without regular, proactive communication, they fill gaps with assumptions — usually negative.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.80567+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('801', 'RC-801', '92', 'Founder Underestimating Time Cost of Investor Management', 'Behavioural', 'The founder did not anticipate how much time managing a growing investor base would require. Time spent on investor relations displaces time building the business.', '0.72', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:35.220106+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('802', 'RC-802', '93', 'No Protected Strategic Thinking Time in Founder Calendar', 'Operational', 'The founder calendar is entirely reactive. Without protected time for strategic thinking, long-term direction gets defined by default rather than by design.', '0.80', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:40.388994+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('803', 'RC-803', '93', 'Operational Urgency Consistently Wins Over Strategic Importance', 'Psychological', 'Urgent tasks trigger a stress response that makes them feel more important than they are. Strategic thinking, which has no immediate deadline, is continuously deprioritised.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:35.268465+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('804', 'RC-804', '93', 'Strategy Not Documented or Widely Communicated', 'Operational', 'Even where strategic thinking occurs, it is not documented or communicated across the organisation. The team cannot execute a strategy they have never seen.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:35.313862+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('805', 'RC-805', '94', 'Structure Seen as Enemy of Innovation', 'Psychological', 'The founder believes that adding process will slow down creative thinking. This false dichotomy prevents the organisation from building the structure needed for quality without sacrificing agility.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:35.361019+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('806', 'RC-806', '94', 'No Ambidextrous Operating Model Designed', 'Strategic', 'The company never built a model for managing core business operations and innovation simultaneously. Resources allocated to either/or rather than to both in parallel.', '0.75', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:12:16.950432+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('807', 'RC-807', '94', 'New Capabilities Launched Without Operational Support', 'Operational', 'Innovation produces new products and features that are launched without the operational infrastructure — support, documentation, monitoring — needed to sustain them reliably.', '0.78', 'external', '2026-07-10 14:16:03.417981+00', '2026-08-03 03:11:31.362974+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('808', 'RC-808', '22', 'No Access to Founder Networks', 'Operational', 'The founder has never been in circles where credible co-founders are met, so the search never realistically starts.', '0.72', 'external', '2026-07-25 14:26:46.300271+00', '2026-08-03 03:11:26.826565+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('809', 'RC-809', '22', 'Unwilling to Share Equity', 'Behavioural', 'Reluctance to give up meaningful ownership rules out the calibre of co-founder worth having.', '0.76', 'external', '2026-07-25 14:26:46.300271+00', '2026-08-03 03:11:26.877184+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('810', 'RC-810', '22', 'Difficulty Trusting Others With the Vision', 'Psychological', 'A belief that nobody will care about the idea as much as they do keeps the founder working alone by choice.', '0.75', 'external', '2026-07-25 14:26:46.300271+00', '2026-08-03 03:11:26.923009+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('811', 'RC-811', '22', 'Critical Skill Gaps Left Unfilled', 'Operational', 'The founder covers functions they are not equipped for, so weak areas stay permanently weak.', '0.78', 'external', '2026-07-25 14:26:46.300271+00', '2026-08-03 03:11:28.392904+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('812', 'RC-812', '22', 'Decisions Made Without Challenge', 'Strategic', 'With no peer to pressure-test choices, poor decisions travel a long way before anyone questions them.', '0.77', 'external', '2026-07-25 14:26:46.300271+00', '2026-08-03 03:11:28.444905+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('813', 'RC-813', '22', 'Founder Bandwidth Ceiling', 'Operational', 'Every function competes for one person''s hours, so growth stalls at whatever one person can personally carry.', '0.78', 'external', '2026-07-25 14:26:46.300271+00', '2026-08-03 03:11:28.495391+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('814', 'RC-814', '22', 'Isolation With No Sounding Board', 'Psychological', 'The emotional load of the business is carried alone, which distorts judgement during hard periods.', '0.74', 'external', '2026-07-25 14:26:46.300271+00', '2026-08-03 03:11:28.545776+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('815', 'RC-815', '22', 'Previous Co-founder Fallout', 'Psychological', 'A painful earlier partnership makes the founder avoid ever sharing control again, regardless of current need.', '0.73', 'external', '2026-07-25 14:26:46.300271+00', '2026-08-03 03:11:28.598047+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('816', 'RC-816', '24', 'No Board or Advisory Structure', 'Operational', 'No one outside the company reviews major decisions, so there is no independent check on the founder''s judgement.', '0.77', 'external', '2026-07-25 14:28:19.652936+00', '2026-08-03 03:11:27.019755+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('817', 'RC-817', '24', 'All Decision Rights Held by the Founder', 'Behavioural', 'Every approval routes through one person, so oversight depends entirely on that person choosing to seek it.', '0.78', 'external', '2026-07-25 14:28:19.652936+00', '2026-08-03 03:11:27.069497+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('818', 'RC-818', '24', 'Decision Rights Never Defined', 'Operational', 'Nobody knows who is allowed to approve what, so decisions get made ad hoc by whoever is closest to the issue.', '0.78', 'external', '2026-07-25 14:28:19.652936+00', '2026-08-03 03:11:27.116771+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('819', 'RC-819', '24', 'Governance Treated as Bureaucracy', 'Behavioural', 'Oversight is seen as red tape that slows a startup down, so it is deliberately skipped in favour of speed.', '0.75', 'external', '2026-07-25 14:28:19.652936+00', '2026-08-03 03:11:28.644349+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('820', 'RC-820', '24', 'No Documented Policies or Approval Limits', 'Operational', 'Nothing is written down, so consistency depends on memory and whoever happens to be asked.', '0.76', 'external', '2026-07-25 14:28:19.652936+00', '2026-08-03 03:11:28.690432+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('821', 'RC-821', '24', 'Financial Controls Never Established', 'Operational', 'Money moves without approval thresholds or separation of duties, so errors and misuse go undetected.', '0.79', 'external', '2026-07-25 14:28:19.652936+00', '2026-08-03 03:11:28.741896+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('822', 'RC-822', '24', 'Investor and Stakeholder Reporting Treated as Optional', 'Strategic', 'Updates are irregular and reactive, so problems surface to stakeholders far later than they should.', '0.74', 'external', '2026-07-25 14:28:19.652936+00', '2026-08-03 03:11:28.788232+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('823', 'RC-823', '24', 'Conflicts of Interest Left Unmanaged', 'Strategic', 'Related-party dealings and personal relationships are never declared, creating risk nobody is tracking.', '0.73', 'external', '2026-07-25 14:28:19.652936+00', '2026-08-03 03:11:28.342741+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('824', 'RC-824', '27', 'Valuation Chased Over Fit', 'Strategic', 'The round is optimised for the headline number rather than the right amount from the right investor.', '0.74', 'external', '2026-07-25 14:29:07.560307+00', '2026-08-03 03:11:27.225122+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('825', 'RC-825', '27', 'Capital Raised Before Product-Market Fit Is Proven', 'Strategic', 'Money arrives before the model is validated, so it funds guessing at scale instead of learning cheaply.', '0.80', 'external', '2026-07-25 14:29:07.560307+00', '2026-08-03 03:11:27.271892+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('826', 'RC-826', '27', 'Fundraising Treated as the Milestone', 'Behavioural', 'Closing a round is celebrated as success in itself, which hides the fact that nothing has been proven yet.', '0.75', 'external', '2026-07-25 14:29:07.560307+00', '2026-08-03 03:11:27.318365+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('827', 'RC-827', '27', 'Spending Discipline Erodes With a Large Balance', 'Behavioural', 'A full bank account removes the constraint that was forcing sharp decisions, and standards quietly drop.', '0.79', 'external', '2026-07-25 14:29:07.560307+00', '2026-08-03 03:11:28.976327+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('828', 'RC-828', '27', 'Premature Scaling of Team and Fixed Costs', 'Operational', 'Headcount and commitments grow ahead of revenue simply because the cash allows it, not because demand requires it.', '0.80', 'external', '2026-07-25 14:29:07.560307+00', '2026-08-03 03:11:29.023905+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('829', 'RC-829', '27', 'Excessive Dilution Before Value Inflection', 'Strategic', 'Too much equity is given away before the business is worth much, which constrains every future round.', '0.77', 'external', '2026-07-25 14:29:07.560307+00', '2026-08-03 03:11:29.072777+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('830', 'RC-830', '27', 'Unrealistic Milestones Attached to the Round', 'Strategic', 'The raise sets growth expectations the business has no realistic path to meeting in the time available.', '0.76', 'external', '2026-07-25 14:29:07.560307+00', '2026-08-03 03:11:28.832324+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('831', 'RC-831', '27', 'Investor Expectations Misaligned With Founder Pace', 'Strategic', 'A large cheque brings demands for a speed and scale of growth the founder never actually intended to pursue.', '0.74', 'external', '2026-07-25 14:29:07.560307+00', '2026-08-03 03:11:29.169959+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('832', 'RC-832', '32', 'Fundraise Timeline Underestimated', 'Strategic', 'The raise is planned as a six to eight week exercise when it realistically takes four to six months, so the runway maths was wrong from day one.', '0.81', 'external', '2026-07-25 14:32:26.366765+00', '2026-08-03 03:11:27.429903+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('833', 'RC-833', '32', 'Fundraising Started Too Late', 'Strategic', 'The process begins when runway is already short, which removes any ability to walk away from a bad offer.', '0.79', 'external', '2026-07-25 14:32:26.366765+00', '2026-08-03 03:11:27.478057+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('834', 'RC-834', '32', 'Founder Attention Fully Diverted to Raising', 'Operational', 'The founder disappears into investor meetings and the business stalls, so the metrics being pitched start declining mid-process.', '0.78', 'external', '2026-07-25 14:32:26.366765+00', '2026-08-03 03:11:27.525137+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('835', 'RC-835', '32', 'Spending Continued at Pre-Raise Burn Rate', 'Behavioural', 'Burn is never cut when the raise starts because the money is assumed to be arriving, so every week of delay costs full price.', '0.80', 'external', '2026-07-25 14:32:26.366765+00', '2026-08-03 03:11:29.216416+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('836', 'RC-836', '32', 'No Bridge or Fallback Financing Plan', 'Strategic', 'There is no plan B if the round slips or falls through, so a delay becomes an emergency rather than an inconvenience.', '0.79', 'external', '2026-07-25 14:32:26.366765+00', '2026-08-03 03:11:29.262961+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('837', 'RC-837', '32', 'Growth Spending Increased to Look Attractive in Diligence', 'Behavioural', 'Spend is pushed up to show traction during the process, accelerating burn at exactly the moment cash is tightest.', '0.75', 'external', '2026-07-25 14:32:26.366765+00', '2026-08-03 03:11:29.120733+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('838', 'RC-838', '32', 'Weak Cash Flow Visibility', 'Operational', 'The founder has no accurate live runway figure, so the danger point is discovered late rather than anticipated.', '0.80', 'external', '2026-07-25 14:32:26.366765+00', '2026-08-03 03:11:16.311756+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('839', 'RC-839', '32', 'Shrinking Runway Weakens Negotiating Position', 'Strategic', 'As cash drains, terms that would have been refused become acceptable, and the round closes worse than it should have.', '0.77', 'external', '2026-07-25 14:32:26.366765+00', '2026-08-03 03:11:29.356087+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('840', 'RC-840', '38', 'Revenue Pressure From Runway or Investors', 'Strategic', 'A short-term cash need overrides product judgement, so decisions get made for this quarter rather than for the user.', '0.77', 'external', '2026-07-25 14:33:13.377633+00', '2026-08-03 03:11:27.616622+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('841', 'RC-841', '38', 'Monetisation Added Before Value Is Proven', 'Strategic', 'Charging begins before users reliably get value, so the product asks for money it has not yet earned.', '0.80', 'external', '2026-07-25 14:33:13.377633+00', '2026-08-03 03:11:27.669336+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('842', 'RC-842', '38', 'Paywall Placed on the Core Value', 'Strategic', 'The exact thing users came for is locked behind payment, so the product stops delivering on its own promise.', '0.79', 'external', '2026-07-25 14:33:13.377633+00', '2026-08-03 03:11:27.715767+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('843', 'RC-843', '38', 'Short-Term Metrics Drive Product Decisions', 'Behavioural', 'The team optimises for this month''s revenue over retention, and the damage only shows up a few months later.', '0.78', 'external', '2026-07-25 14:33:13.377633+00', '2026-08-03 03:11:29.403901+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('844', 'RC-844', '38', 'No Voice of the Customer in Monetisation Decisions', 'Operational', 'Nobody in the room represents the user when pricing and packaging are decided, so the trade-off is never argued.', '0.76', 'external', '2026-07-25 14:33:13.377633+00', '2026-08-03 03:11:29.451125+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('845', 'RC-845', '38', 'Aggressive Ads and Upsells Degrade the Experience', 'Operational', 'The product becomes noisier and harder to use as more revenue surfaces are added on top of it.', '0.75', 'external', '2026-07-25 14:33:13.377633+00', '2026-08-03 03:11:28.878077+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('846', 'RC-846', '38', 'Churn Signals Ignored or Rationalised', 'Behavioural', 'Users leaving is explained away as the wrong segment rather than treated as direct feedback on the change.', '0.79', 'external', '2026-07-25 14:33:13.377633+00', '2026-08-03 03:11:29.542673+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('847', 'RC-847', '38', 'Pricing Set Without Understanding Willingness to Pay', 'Knowledge', 'Price and packaging are guessed rather than researched, so the model lands badly and gets patched with more monetisation.', '0.76', 'external', '2026-07-25 14:33:13.377633+00', '2026-08-03 03:11:29.589335+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('848', 'RC-848', '39', 'Market Readiness Never Assessed', 'Strategic', 'Nobody checked whether buyers are actually ready to adopt this yet, so the product arrives into a market that is not looking for it.', '0.80', 'external', '2026-07-25 14:33:57.753933+00', '2026-08-03 03:11:27.812905+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('849', 'RC-849', '39', 'Building Ahead of Enabling Infrastructure', 'Strategic', 'The product depends on adoption, technology or regulation that has not arrived yet, so it works but nobody can use it properly.', '0.78', 'external', '2026-07-25 14:33:57.753933+00', '2026-08-03 03:11:27.859907+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('850', 'RC-850', '39', 'Launched Too Late Into an Already Crowded Market', 'Strategic', 'Competitors have already defined the category and captured the early buyers by the time launch happens.', '0.77', 'external', '2026-07-25 14:33:57.753933+00', '2026-08-03 03:11:27.90876+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('851', 'RC-851', '39', 'Long Build Cycle Detached From Market Signals', 'Operational', 'The team builds for months without re-checking whether the window is still open, so the plan is validated against an old market.', '0.79', 'external', '2026-07-25 14:33:57.753933+00', '2026-08-03 03:11:29.733332+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('852', 'RC-852', '39', 'Trend Mistaken for Durable Demand', 'Knowledge', 'A temporary spike in interest is read as a lasting market, and the product is built for a wave that has already passed.', '0.76', 'external', '2026-07-25 14:33:57.753933+00', '2026-08-03 03:11:29.780001+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('853', 'RC-853', '39', 'Customer Budget Cycles Ignored', 'Knowledge', 'The offer arrives at a point in the year when buyers have no budget allocated, so genuine interest cannot convert.', '0.74', 'external', '2026-07-25 14:33:57.753933+00', '2026-08-03 03:11:29.825472+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('854', 'RC-854', '39', 'Regulatory or Policy Shift Not Anticipated', 'Strategic', 'A rule change quietly opens or closes the window and nobody was tracking it closely enough to react in time.', '0.75', 'external', '2026-07-25 14:33:57.753933+00', '2026-08-03 03:11:29.308944+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('855', 'RC-855', '39', 'Launch Timed Around Internal Readiness Rather Than Market Demand', 'Behavioural', 'The date is set by when the team finishes building, not by when buyers are ready to buy.', '0.79', 'external', '2026-07-25 14:33:57.753933+00', '2026-08-03 03:11:29.919355+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('856', 'RC-856', '43', 'No Separation Between Personal and Business Finances', 'Operational', 'Money moves between the founder and the company without a clean boundary, so no figure the business produces can be trusted.', '0.81', 'external', '2026-07-25 14:34:46.017324+00', '2026-08-03 03:11:28.006387+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
