insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('861', 'RC-861', '43', 'Invoicing and Collections Not Tracked', 'Operational', 'Money already earned goes uncollected because no one is systematically chasing what is owed.', '0.78', 'external', '2026-07-25 14:34:46.017324+00', '2026-08-03 03:11:28.925719+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('862', 'RC-862', '43', 'No Finance Owner Appointed', 'Operational', 'Nobody is accountable for the numbers, so financial work only happens when someone happens to find time for it.', '0.79', 'external', '2026-07-25 14:34:46.017324+00', '2026-08-03 03:11:30.108729+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
