insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('885', 'RC-885', '98', 'Runway Anxiety Driving Short-Term Reactions', 'Psychological', 'A shrinking cash position makes every decision feel urgent, which crowds out considered judgement.', '0.79', 'internal', '2026-07-25 15:22:07.624059+00', '2026-08-03 03:11:34.363331+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
