insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('965', 'RC-965', '112', 'Always Available to Everyone', 'Behavioural', 'Constant reachability means the founder day belongs to whoever needs them, not to what the business needs.', '0.79', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:38.666403+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('966', 'RC-966', '112', 'Weak Systems Generating Real Emergencies', 'Operational', 'Poor process genuinely creates fires, so reactivity is partly a symptom rather than only a habit.', '0.79', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:38.854233+00', 'Stage 1→10+', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('967', 'RC-967', '112', 'No Weekly Review to Reset Priorities', 'Operational', 'Without a regular step back, drift is never noticed and the same pattern repeats week after week.', '0.78', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:38.712505+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('968', 'RC-968', '119', 'Expected Timeline Far Shorter Than Reality', 'Knowledge', 'The founder budgeted emotionally for a fraction of the time things actually take, so normal progress feels like failure.', '0.80', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:38.911078+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('969', 'RC-969', '119', 'Comparing Own Middle to Others Highlights', 'Psychological', 'Public success stories are compared against private struggle, making ordinary difficulty look like being behind.', '0.79', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:38.958468+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('970', 'RC-970', '119', 'No Interim Milestones to Mark Progress', 'Operational', 'With only a distant end goal, months of real progress produce no sense of movement.', '0.79', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:39.146455+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('971', 'RC-971', '119', 'Switching to a New Idea When Difficulty Rises', 'Behavioural', 'A fresh idea arrives at exactly the moment the current one gets hard, and the switch is mistaken for insight.', '0.80', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:39.00592+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('972', 'RC-972', '119', 'Motivation Dependent on Visible Wins', 'Psychological', 'Effort is sustained by external validation, so long unrewarded stretches drain commitment entirely.', '0.78', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:39.195328+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('973', 'RC-973', '119', 'No Support Structure During Low Periods', 'Operational', 'There is nobody holding the founder to the commitment when their own conviction dips.', '0.77', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:39.053051+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('974', 'RC-974', '121', 'Every Day Structured Differently', 'Behavioural', 'With no repeating shape to the day, energy goes into deciding what to do rather than doing it.', '0.78', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:39.242678+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('975', 'RC-975', '121', 'Routine Equated With Rigidity', 'Psychological', 'Structure is seen as the opposite of the freedom the founder started the business for, so it is resisted.', '0.76', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:39.098783+00', 'Stage 0', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('976', 'RC-976', '121', 'Deep Work Never Scheduled', 'Operational', 'The hardest thinking is left to whenever there is a gap, so it happens at the worst hours or not at all.', '0.80', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:39.289782+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('977', 'RC-977', '121', 'Day Starts With Messages and Notifications', 'Behavioural', 'The first hour is given to other people agendas, which sets a reactive tone for everything after it.', '0.79', 'internal', '2026-07-25 15:24:15.793978+00', '2026-08-03 03:11:39.335629+00', 'Stage 0→1', 'text-embedding-3-small', 'v2', '1536') on conflict do nothing;
