insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1001', 'RC-1001', '126', 'Leading Questions in Interviews', 'Knowledge', 'When discovery conversations do happen, questions are phrased to confirm the idea rather than to uncover the truth.', '0.68', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:29.665396+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1002', 'RC-1002', '126', 'Premature Solution Pitching', 'Behavioural', 'The founder pitches the product instead of listening for the problem, so real customer language never surfaces.', '0.68', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:29.733041+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1003', 'RC-1003', '126', 'Discomfort with Ambiguity', 'Psychological', 'Open-ended conversations without a script feel unstructured and uncomfortable, so the founder avoids running enough of them.', '0.62', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:29.783536+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1004', 'RC-1004', '126', 'No System for Capturing Insights', 'Operational', 'Even where conversations happen, there is no consistent way notes are recorded, so patterns across interviews are never noticed.', '0.65', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:29.83654+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1005', 'RC-1005', '127', 'Persona Built in a Single Sitting', 'Behavioural', 'The persona document was written in one brainstorming session rather than updated as real evidence came in.', '0.65', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:29.888912+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1006', 'RC-1006', '127', 'Confusing a Buyer Persona with a User Persona', 'Knowledge', 'In B2B or multi-sided products, the founder has not distinguished who pays from who uses the product day to day.', '0.70', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:29.940975+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1007', 'RC-1007', '127', 'Anchoring on the First Customer', 'Behavioural', 'The founder generalises the whole market from the traits of the very first person who showed interest.', '0.68', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:29.994232+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1008', 'RC-1008', '127', 'No Refresh Cycle for the Persona', 'Operational', 'The persona was written once at the start and has never been revisited even though the founder has since learned more.', '0.62', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.046889+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1009', 'RC-1009', '127', 'Overreliance on Demographics', 'Knowledge', 'The persona focuses on age, income, or job title but says nothing about the customer''s actual triggers, fears, or buying behaviour.', '0.68', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.099254+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1010', 'RC-1010', '127', 'Copying a Competitor''s Stated Customer', 'Strategic', 'The founder assumed a competitor''s public messaging accurately reflects who is really buying, without independent verification.', '0.62', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.155045+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1011', 'RC-1011', '128', 'Belief That ''No Competitors'' Means Validation', 'Psychological', 'The founder treats the absence of visible competitors as proof of opportunity rather than a possible warning sign about demand.', '0.65', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.205714+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1012', 'RC-1012', '128', 'Only Looking at Direct Competitors', 'Knowledge', 'The founder searches for companies doing exactly the same thing and misses indirect alternatives and manual workarounds that are the real competition.', '0.70', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.256912+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1013', 'RC-1013', '128', 'No Repeatable Research Process', 'Operational', 'Competitor research was a one-time exercise rather than an ongoing habit, so the picture is already stale.', '0.62', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.307394+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1014', 'RC-1014', '128', 'Avoidance of Discouraging Information', 'Psychological', 'Looking closely at strong competitors feels threatening to the founder''s confidence in the idea, so the research is kept shallow on purpose.', '0.68', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.358642+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1015', 'RC-1015', '128', 'Overestimating Differentiation', 'Behavioural', 'The founder assumes their solution is obviously better without having used competitor products directly.', '0.65', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.412104+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1016', 'RC-1016', '128', 'Ignoring the ''Do Nothing'' Competitor', 'Strategic', 'The founder has not considered that the customer''s current default — doing nothing or tolerating the problem — is itself the hardest competitor to beat.', '0.70', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.465897+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1017', 'RC-1017', '128', 'No Tracking of Competitor Pricing or Messaging', 'Operational', 'There''s no system for noticing when competitors change their pricing, positioning, or offering.', '0.60', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.516084+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1018', 'RC-1018', '129', 'Cost-Plus Default Without Market Check', 'Knowledge', 'Price was built up from the founder''s own costs without ever comparing it to what the market already pays for alternatives.', '0.68', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.566346+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1019', 'RC-1019', '129', 'Fear of Charging What It''s Worth', 'Psychological', 'The founder underprices because charging a fair price feels uncomfortable or risks rejection.', '0.65', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.616701+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1020', 'RC-1020', '129', 'No Competitor Pricing Research Done', 'Operational', 'There has been no deliberate effort to find out what direct or indirect competitors charge.', '0.65', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.66921+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1021', 'RC-1021', '129', 'Round Number Anchoring', 'Behavioural', 'Price was picked because it was a clean, easy number to say out loud, not because of any analysis.', '0.58', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.722105+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1022', 'RC-1022', '129', 'Assuming Premium Positioning Without Evidence', 'Strategic', 'The founder wants to be seen as premium but hasn''t validated that the product currently delivers premium-level value relative to alternatives.', '0.62', 'external', '2026-08-03 06:11:34.594992+00', '2026-08-03 06:14:30.771671+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1023', 'RC-1023', '130', 'No Knowledge of CAC or LTV', 'Knowledge', 'The founder cannot state, even roughly, what it costs to acquire a customer or what that customer is worth over time.', '0.72', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.051095+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1024', 'RC-1024', '130', 'Revenue Tracked, Cost Per Sale Ignored', 'Operational', 'Total revenue is monitored closely but the direct cost of delivering each sale is not broken out separately.', '0.68', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.111321+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1025', 'RC-1025', '130', 'Avoidance of Uncomfortable Math', 'Psychological', 'The founder suspects the numbers may not work and avoids calculating them precisely to protect their confidence in the idea.', '0.65', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.165884+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1026', 'RC-1026', '130', 'Confusing Revenue with Profit', 'Knowledge', 'Top-line sales growth is treated as proof of a healthy business, without checking what remains after real costs.', '0.70', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.220605+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1027', 'RC-1027', '130', 'No Financial Modeling Skill', 'Knowledge', 'The founder has never built even a basic spreadsheet model connecting costs, pricing, and volume.', '0.68', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.276252+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
