insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1029', 'RC-1029', '130', 'No Trigger Point for Reviewing Unit Economics', 'Operational', 'There is no habit or checkpoint for revisiting the numbers as pricing, costs, or channels change.', '0.60', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.384218+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1030', 'RC-1030', '131', 'Copying a Competitor''s Model Without Fit-Testing', 'Behavioural', 'The revenue model was adopted because a competitor or admired company uses it, without checking whether it fits this business''s own cost structure and customer base.', '0.68', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.43512+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1031', 'RC-1031', '131', 'Only One Model Ever Considered', 'Knowledge', 'The founder is not aware of the range of revenue model options (subscription, transactional, commission, freemium, licensing, usage-based) available for this type of business.', '0.72', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.489813+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1032', 'RC-1032', '131', 'Model Chosen for Founder Comfort, Not Customer Fit', 'Psychological', 'The revenue model reflects what feels familiar or safe to the founder rather than how the target customer actually prefers to pay.', '0.65', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.54067+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1033', 'RC-1033', '131', 'No Testing of Willingness to Pay Under the Chosen Model', 'Operational', 'The specific payment structure (e.g. monthly vs annual, per-seat vs flat fee) has never been validated with real customers.', '0.65', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.61312+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1034', 'RC-1034', '131', 'Revenue Model Locked In Too Early', 'Strategic', 'The model was fixed at the idea stage and has never been revisited despite new evidence about how customers actually behave.', '0.62', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.672121+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1035', 'RC-1035', '131', 'Mismatch Between Model and Sales Cycle', 'Strategic', 'The chosen revenue model (e.g. high-touch subscription) does not match how quickly or slowly this type of customer actually makes buying decisions.', '0.62', 'external', '2026-08-03 06:23:02.800809+00', '2026-08-03 06:24:44.731551+00', 'Stage 0', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
