insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1037', 'RC-1037', '132', 'Hidden Costs Excluded from the Model', 'Operational', 'Costs like support, returns, or maintenance are left out of the picture entirely, inflating perceived profitability.', '0.65', 'external', '2026-08-03 06:44:27.143042+00', '2026-08-03 06:45:59.199207+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1038', 'RC-1038', '132', 'Cost Structure Copied from a Different Business Type', 'Behavioural', 'Assumptions about costs were borrowed from a different kind of business (e.g. digital vs physical) without checking they actually apply.', '0.62', 'external', '2026-08-03 06:44:27.143042+00', '2026-08-03 06:45:59.265903+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1039', 'RC-1039', '132', 'No Scenario Planning for Cost at Scale', 'Strategic', 'The founder has not modeled what costs look like at 10x or 100x current volume.', '0.60', 'external', '2026-08-03 06:44:27.143042+00', '2026-08-03 06:45:59.32907+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1040', 'RC-1040', '132', 'One-Time Costs Treated as Ongoing, or Vice Versa', 'Knowledge', 'Setup or acquisition costs are confused with recurring operational costs, distorting the real cost picture.', '0.62', 'external', '2026-08-03 06:44:27.143042+00', '2026-08-03 06:45:59.390089+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1041', 'RC-1041', '132', 'No Owner for Cost Tracking', 'Operational', 'Nobody is responsible for keeping the cost side of the model updated as the business changes.', '0.58', 'external', '2026-08-03 06:44:27.143042+00', '2026-08-03 06:45:59.447434+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1042', 'RC-1042', '133', 'No Early Warning System for Competitor Moves', 'Operational', 'There''s no way the founder would find out quickly if a competitor made a significant change.', '0.62', 'external', '2026-08-03 06:44:27.143042+00', '2026-08-03 06:45:59.505935+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1043', 'RC-1043', '133', 'Belief That Reacting Fast Is Enough', 'Psychological', 'The founder assumes they can figure out a response in the moment, without ever having thought through likely scenarios in advance.', '0.60', 'external', '2026-08-03 06:44:27.143042+00', '2026-08-03 06:45:59.558695+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1044', 'RC-1044', '133', 'No Defensible Moat Identified', 'Strategic', 'The founder has not identified what would actually stop a competitor from copying their most successful feature or offer.', '0.68', 'external', '2026-08-03 06:44:27.143042+00', '2026-08-03 06:45:59.614938+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1045', 'RC-1045', '133', 'Price War Vulnerability', 'Strategic', 'The business has no plan for what happens if a well-funded competitor cuts prices below what this business can sustainably match.', '0.65', 'external', '2026-08-03 06:44:27.143042+00', '2026-08-03 06:45:59.671159+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
