insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1063', 'RC-1063', '136', 'No Opportunity Cost Comparison', 'Knowledge', 'What the founder would have to give up (time, focus, resources) to pursue this opportunity is never explicitly weighed against what pursuing it might yield.', '0.70', 'external', '2026-08-03 07:21:29.977684+00', '2026-08-03 07:23:25.481332+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
