insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1145', 'RC-1145', '149', 'Moving Too Fast to Ever Look Back', 'Behavioural', 'The pace of the business means attention is always on the next decision, never on reviewing the last one.', '0.62', 'external', '2026-08-03 11:00:51.857487+00', '2026-08-03 11:01:50.641257+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1146', 'RC-1146', '149', 'No Distinction Between Good Decisions and Good Outcomes', 'Knowledge', 'A good outcome from a rushed decision is treated as validation of the process, when it may have just been luck.', '0.65', 'external', '2026-08-03 11:00:51.857487+00', '2026-08-03 11:01:50.692584+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
