insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1148', 'RC-1148', '150', 'Team Never Asked About Capacity or Feasibility', 'Operational', 'The people who would have to execute on a new opportunity are never asked whether it''s realistic given current workload.', '0.65', 'external', '2026-08-03 11:00:51.857487+00', '2026-08-03 11:01:50.789421+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1149', 'RC-1149', '150', 'Blind Spots Team Could Catch Go Unnoticed', 'Strategic', 'Team members closer to customers or operations might see risks or flaws in an opportunity that the founder, working from a distance, would miss.', '0.65', 'external', '2026-08-03 11:00:51.857487+00', '2026-08-03 11:01:50.836499+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1150', 'RC-1150', '150', 'Decisions Announced, Not Discussed', 'Behavioural', 'By the time the team hears about a new opportunity being pursued, it''s already been decided rather than discussed.', '0.60', 'external', '2026-08-03 11:00:51.857487+00', '2026-08-03 11:01:50.881339+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
