insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1152', 'RC-1152', '150', 'Fear That Consulting Others Slows Decisions Down', 'Psychological', 'The founder avoids involving others because it feels like it would slow down decisive action.', '0.58', 'external', '2026-08-03 11:00:51.857487+00', '2026-08-03 11:01:50.975649+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1153', 'RC-1153', '151', 'Plan Never Shared With the Team', 'Operational', 'Whatever planning happens stays with the founder and is never distributed or discussed with those who need to execute it.', '0.68', 'external', '2026-08-03 11:12:40.863128+00', '2026-08-03 11:13:55.584329+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1154', 'RC-1154', '151', 'Belief That the Team Doesn''t Need the Full Picture', 'Psychological', 'The founder assumes the team only needs task-level direction, not visibility into the broader plan.', '0.62', 'external', '2026-08-03 11:12:40.863128+00', '2026-08-03 11:13:55.641309+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1155', 'RC-1155', '151', 'No Format Exists to Communicate the Plan', 'Operational', 'Even if the founder wanted to share the plan, there''s no simple format or document that makes it easy to communicate.', '0.62', 'external', '2026-08-03 11:12:40.863128+00', '2026-08-03 11:13:55.691469+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
