insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1162', 'RC-1162', '152', 'No Buffer for the Unexpected', 'Strategic', 'Plans assume everything goes smoothly, with no time or resource buffer for inevitable delays or surprises.', '0.62', 'external', '2026-08-03 11:12:40.863128+00', '2026-08-03 11:13:56.026457+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1163', 'RC-1163', '152', 'Hiring or Resourcing Needs Identified Too Late', 'Operational', 'The need for more people or budget is only recognized once the plan is already failing to progress, rather than planned for upfront.', '0.62', 'external', '2026-08-03 11:12:40.863128+00', '2026-08-03 11:13:56.071804+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1164', 'RC-1164', '152', 'Plan Ambition Driven by Hope, Not Capacity Data', 'Behavioural', 'Goals are set based on what the founder hopes is possible, rather than grounded in actual historical capacity or throughput.', '0.60', 'external', '2026-08-03 11:12:40.863128+00', '2026-08-03 11:13:56.119819+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1165', 'RC-1165', '153', 'Contracts Never Professionally Reviewed', 'Operational', 'Agreements with customers, vendors, or partners were used or signed without expert review of the risk they carry.', '0.68', 'external', '2026-08-03 11:17:14.846403+00', '2026-08-03 11:18:15.861292+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1166', 'RC-1166', '153', 'Regulatory Obligations Not Fully Understood', 'Knowledge', 'The founder isn''t certain which regulations actually apply to the business, or whether the business is fully compliant.', '0.68', 'external', '2026-08-03 11:17:14.846403+00', '2026-08-03 11:18:15.939145+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1167', 'RC-1167', '153', 'Intellectual Property Left Unprotected', 'Operational', 'Trademarks, key content, or product IP have not been protected, leaving them vulnerable to copying or dispute.', '0.65', 'external', '2026-08-03 11:17:14.846403+00', '2026-08-03 11:18:15.992259+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1168', 'RC-1168', '153', 'Legal Review Postponed as Too Expensive or Unnecessary', 'Psychological', 'Legal review feels like a cost to avoid rather than a risk to manage, especially while the business is still small.', '0.62', 'external', '2026-08-03 11:17:14.846403+00', '2026-08-03 11:18:16.057709+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1169', 'RC-1169', '153', 'No Relationship with a Lawyer or Compliance Advisor', 'Operational', 'There''s no ongoing relationship with legal expertise to call on, so issues only get addressed reactively when something goes wrong.', '0.62', 'external', '2026-08-03 11:17:14.846403+00', '2026-08-03 11:18:16.148392+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
