insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1174', 'RC-1174', '154', 'Team Members Unaware They''re Expected to Watch for a Risk', 'Knowledge', 'Even if the founder mentally assigns a risk to someone, that person often doesn''t know they''re expected to monitor it.', '0.62', 'external', '2026-08-03 11:17:14.846403+00', '2026-08-03 11:18:16.399903+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
