insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1178', 'RC-1178', '155', 'Purchase Frequency Guessed, Not Observed', 'Operational', 'How often customers are expected to buy again was assumed at the start and never verified against real repeat-purchase data.', '0.65', 'external', '2026-08-03 11:28:47.796438+00', '2026-08-03 11:29:40.235213+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1179', 'RC-1179', '155', 'Referral Assumption Baked in Without Evidence', 'Strategic', 'The model counts on word-of-mouth or referrals at a certain rate that has never actually been observed or measured.', '0.65', 'external', '2026-08-03 11:28:47.796438+00', '2026-08-03 11:29:40.292324+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
