insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1189', 'RC-1189', '156', 'No Disqualification Habit', 'Behavioural', 'Once a lead enters the pipeline, there''s no practice of actively removing poor-fit leads — they just linger.', '0.60', 'external', '2026-08-03 12:57:17.857699+00', '2026-08-03 12:58:10.166504+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
