insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1192', 'RC-1192', '157', 'No Testing of What Actually Gets Responses', 'Operational', 'Different versions of outreach have never been compared to see which gets better response rates.', '0.65', 'external', '2026-08-03 13:25:50.183633+00', '2026-08-03 13:26:53.936194+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
