insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1197', 'RC-1197', '158', 'No Reusable Proposal Template', 'Operational', 'Every proposal is built from scratch, with no base template to save time and ensure consistency.', '0.68', 'external', '2026-08-03 13:30:06.16355+00', '2026-08-03 13:30:58.341937+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
