insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1202', 'RC-1202', '158', 'Proposal Written to Impress, Not to Be Understood', 'Behavioural', 'Proposals use jargon or try to sound sophisticated rather than being written for clarity and easy decision-making.', '0.60', 'external', '2026-08-03 13:30:06.16355+00', '2026-08-03 13:30:58.613632+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
