insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1204', 'RC-1204', '159', 'No Defined Follow-Up Cadence', 'Operational', 'There''s no set rhythm (e.g. day 1, 3, 7, 14) for following up with a prospect — it happens whenever the founder remembers.', '0.68', 'external', '2026-08-03 15:50:09.899288+00', '2026-08-03 15:51:12.665485+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
