insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1327', 'RC-1327', '177', 'Policies Communicated Verbally and Inconsistently', 'Behavioural', 'Whatever rules or expectations exist get communicated verbally, differently to different people, rather than in one consistent written source.', '0.60', 'external', '2026-08-03 19:18:54.268294+00', '2026-08-03 19:20:03.356466+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
