insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1329', 'RC-1329', '177', 'Policy Gaps Only Noticed After a Problem Arises', 'Behavioural', 'The absence of a policy only becomes visible reactively, once a specific situation exposes the gap.', '0.60', 'external', '2026-08-03 19:18:54.268294+00', '2026-08-03 19:20:03.47139+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1330', 'RC-1330', '178', 'No Lead Scoring Criteria Defined', 'Knowledge', 'There''s no point-based or ranked system for scoring leads against each other on likely fit or urgency.', '0.68', 'external', '2026-08-04 05:13:53.57963+00', '2026-08-04 05:15:00.547402+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
