insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1335', 'RC-1335', '178', 'High-Value Leads Sometimes Missed in the Noise', 'Strategic', 'A genuinely strong lead can get lost among many lower-quality ones because nothing flags it as a priority.', '0.65', 'external', '2026-08-04 05:13:53.57963+00', '2026-08-04 05:15:01.412673+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
