insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1337', 'RC-1337', '179', 'No Distinction Between ''Not a Fit'' and ''Not Ready Yet''', 'Knowledge', 'Leads that are a good fit but poor timing get treated the same as leads that are a genuinely bad fit, rather than being handled differently.', '0.68', 'external', '2026-08-04 05:24:12.900201+00', '2026-08-04 05:25:17.174351+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
