insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1399', 'RC-1399', '187', 'Timeline Expectations Never Aligned Beforehand', 'Knowledge', 'The proposed timeline is set without checking whether it matches what the prospect actually needs or expects.', '0.58', 'external', '2026-08-04 06:31:36.674993+00', '2026-08-04 06:32:44.38795+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1400', 'RC-1400', '188', 'Proposal Sent Without Any Live Walkthrough', 'Behavioural', 'The proposal is emailed or shared and the prospect is left to read and interpret it entirely alone.', '0.68', 'external', '2026-08-04 06:35:28.134019+00', '2026-08-04 06:36:31.604728+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
