insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1402', 'RC-1402', '188', 'Assumes the Document Should Speak for Itself', 'Psychological', 'The founder believes a well-written proposal shouldn''t need a live explanation, so presenting it feels unnecessary.', '0.60', 'external', '2026-08-04 06:35:28.134019+00', '2026-08-04 06:36:31.746102+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1403', 'RC-1403', '188', 'No Preparation for Questions That Might Come Up', 'Operational', 'There''s no anticipation of what the prospect might ask, so responses during any conversation are improvised.', '0.60', 'external', '2026-08-04 06:35:28.134019+00', '2026-08-04 06:36:31.804885+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1404', 'RC-1404', '188', 'Presentation Skipped to Save Time', 'Behavioural', 'Scheduling and running a presentation call feels like extra effort, so it gets skipped in favor of just sending the document.', '0.58', 'external', '2026-08-04 06:35:28.134019+00', '2026-08-04 06:36:31.869579+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1405', 'RC-1405', '188', 'No Clear Point of Contact for Questions After Sending', 'Operational', 'Once sent, there''s no explicit invitation or clear channel for the prospect to ask questions about the proposal.', '0.60', 'external', '2026-08-04 06:35:28.134019+00', '2026-08-04 06:36:31.934064+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1406', 'RC-1406', '188', 'Real-Time Reactions and Concerns Never Observed', 'Knowledge', 'Without a live walkthrough, the founder never sees the prospect''s real-time reactions, which could reveal concerns worth addressing immediately.', '0.62', 'external', '2026-08-04 06:35:28.134019+00', '2026-08-04 06:36:31.991591+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1407', 'RC-1407', '189', 'No Expiration Date on Proposals', 'Operational', 'Proposals remain valid indefinitely, with nothing prompting the prospect to decide by a specific date.', '0.68', 'external', '2026-08-04 06:51:20.787981+00', '2026-08-04 06:52:24.603312+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1408', 'RC-1408', '189', 'No Legitimate Reason for Urgency Identified', 'Knowledge', 'There''s no genuine, honest reason (capacity, pricing change, timing) that would create real urgency for the prospect.', '0.65', 'external', '2026-08-04 06:51:20.787981+00', '2026-08-04 06:52:24.674232+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1409', 'RC-1409', '189', 'Fear of Seeming Pushy by Adding a Deadline', 'Psychological', 'Adding any time pressure feels aggressive or salesy, so it''s avoided entirely.', '0.65', 'external', '2026-08-04 06:51:20.787981+00', '2026-08-04 06:52:24.729986+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1410', 'RC-1410', '189', 'No Follow-Up Tied to Any Deadline', 'Operational', 'Even where some urgency might exist, follow-up isn''t timed around it in any deliberate way.', '0.60', 'external', '2026-08-04 06:51:20.787981+00', '2026-08-04 06:52:24.798845+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1411', 'RC-1411', '189', 'Deals Allowed to Drift Indefinitely', 'Behavioural', 'Without any deadline, stalled deals just sit in limbo rather than reaching a clear yes or no.', '0.62', 'external', '2026-08-04 06:51:20.787981+00', '2026-08-04 06:52:24.852683+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1412', 'RC-1412', '189', 'No Incentive for Deciding Sooner', 'Strategic', 'There''s no reason (bonus, early-bird terms) for a prospect to prefer deciding now over deciding later.', '0.58', 'external', '2026-08-04 06:51:20.787981+00', '2026-08-04 06:52:24.911016+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1413', 'RC-1413', '189', 'Assumes Urgency Isn''t Appropriate for the Business', 'Knowledge', 'The founder assumes creating urgency doesn''t fit their type of business or sale, without testing that assumption.', '0.60', 'external', '2026-08-04 06:51:20.787981+00', '2026-08-04 06:52:24.968372+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
