insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1415', 'RC-1415', '190', 'No Consideration of Other Reasons for Silence', 'Knowledge', 'The founder doesn''t consider that a prospect might just be busy, or the message got lost, rather than genuinely uninterested.', '0.65', 'external', '2026-08-04 06:55:19.301466+00', '2026-08-04 06:56:49.533707+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1416', 'RC-1416', '190', 'Same Follow-Up Approach Regardless of Likely Reason', 'Operational', 'Follow-up messaging doesn''t change based on what might actually explain the silence.', '0.62', 'external', '2026-08-04 06:55:19.301466+00', '2026-08-04 06:56:49.601293+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1417', 'RC-1417', '190', 'No Attempt to Diagnose Why Someone Went Quiet', 'Operational', 'There''s no step taken to actually figure out or ask why a prospect stopped responding.', '0.60', 'external', '2026-08-04 06:55:19.301466+00', '2026-08-04 06:56:49.661451+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1418', 'RC-1418', '190', 'Prospects Given Up on Too Quickly', 'Behavioural', 'The founder stops following up prematurely, assuming disinterest, when the prospect may just need more time or a different approach.', '0.62', 'external', '2026-08-04 06:55:19.301466+00', '2026-08-04 06:56:49.726035+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1419', 'RC-1419', '190', 'No Distinction Between a Soft No and a Hard No', 'Knowledge', 'A prospect who''s genuinely not interested is treated the same as one who''s just delayed, wasting effort on the wrong ones or giving up on the right ones.', '0.60', 'external', '2026-08-04 06:55:19.301466+00', '2026-08-04 06:56:49.789199+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
