insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1421', 'RC-1421', '191', 'Same Follow-Up Type Repeated Even When It''s Not Working', 'Behavioural', 'After multiple unsuccessful attempts, the same kind of touch (e.g. another email) keeps getting used instead of trying something different.', '0.65', 'external', '2026-08-04 10:25:46.984914+00', '2026-08-04 10:26:48.96898+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
