insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1424', 'RC-1424', '191', 'Giving Up Treated as the Only Alternative to Repeating', 'Behavioural', 'When the usual follow-up doesn''t work, the only two options considered are keep repeating or stop entirely — nothing in between.', '0.60', 'external', '2026-08-04 10:25:46.984914+00', '2026-08-04 10:26:49.231943+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1425', 'RC-1425', '191', 'No Attempt to Reach a Different Stakeholder', 'Strategic', 'If the original contact goes quiet, there''s no consideration of reaching someone else at the company who might respond.', '0.60', 'external', '2026-08-04 10:25:46.984914+00', '2026-08-04 10:26:49.296864+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
