insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1428', 'RC-1428', '192', 'No Log of Past Follow-Up Attempts Per Prospect', 'Operational', 'There''s no record showing what''s already been sent to a given prospect and when.', '0.68', 'external', '2026-08-04 10:29:26.959051+00', '2026-08-04 10:30:33.826052+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1429', 'RC-1429', '192', 'Relies Entirely on Memory to Track Follow-Up History', 'Operational', 'Without a system, the founder has to remember who''s been contacted and what was said, which breaks down as volume grows.', '0.68', 'external', '2026-08-04 10:29:26.959051+00', '2026-08-04 10:30:33.899033+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1430', 'RC-1430', '192', 'Risk of Sending Contradictory or Duplicate Messages', 'Behavioural', 'Without a history, a new follow-up might repeat information already sent or contradict an earlier message.', '0.62', 'external', '2026-08-04 10:29:26.959051+00', '2026-08-04 10:30:33.958362+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1431', 'RC-1431', '192', 'No Visibility Into How Long a Prospect Has Been in Follow-Up', 'Knowledge', 'There''s no way to see how long a prospect has been in the follow-up sequence without checking manually.', '0.60', 'external', '2026-08-04 10:29:26.959051+00', '2026-08-04 10:30:34.017096+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1432', 'RC-1432', '192', 'Lost Prospects Never Rediscovered', 'Operational', 'Without tracking, some prospects simply get lost and are never followed up with again, not because a decision was made, but because they were forgotten.', '0.62', 'external', '2026-08-04 10:29:26.959051+00', '2026-08-04 10:30:34.080583+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1433', 'RC-1433', '192', 'No Single Place Housing All Prospect Communication', 'Operational', 'Follow-up history is scattered across email, notes, and memory rather than centralized in one place.', '0.60', 'external', '2026-08-04 10:29:26.959051+00', '2026-08-04 10:30:34.130474+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1434', 'RC-1434', '192', 'System Feels Unnecessary at Current Volume', 'Psychological', 'The founder assumes a formal tracking system isn''t needed yet, even as volume grows past what memory can handle.', '0.58', 'external', '2026-08-04 10:29:26.959051+00', '2026-08-04 10:30:34.17779+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1435', 'RC-1435', '193', 'No Tracking of Response Rates by Follow-Up Attempt Number', 'Operational', 'There''s no data showing whether the 1st, 2nd, or 5th follow-up is actually the one that gets responses.', '0.68', 'external', '2026-08-04 10:33:13.907552+00', '2026-08-04 10:34:23.957665+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1436', 'RC-1436', '193', 'No Comparison of Different Follow-Up Timings', 'Knowledge', 'Different intervals between follow-ups (next day vs next week) have never been compared for effectiveness.', '0.65', 'external', '2026-08-04 10:33:13.907552+00', '2026-08-04 10:34:24.045732+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1437', 'RC-1437', '193', 'Follow-Up Approach Never Adjusted Based on Results', 'Behavioural', 'The same follow-up approach continues indefinitely regardless of whether it''s actually producing results.', '0.65', 'external', '2026-08-04 10:33:13.907552+00', '2026-08-04 10:34:24.106633+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1438', 'RC-1438', '193', 'No Sense of What ''Good'' Follow-Up Performance Looks Like', 'Knowledge', 'There''s no benchmark for what response rate or conversion rate would indicate the follow-up process is working well.', '0.60', 'external', '2026-08-04 10:33:13.907552+00', '2026-08-04 10:34:24.178313+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1439', 'RC-1439', '193', 'Follow-Up Treated as a Fixed Process, Not an Improvable System', 'Psychological', 'Follow-up is seen as just something you do, not a system that can be measured and improved over time.', '0.60', 'external', '2026-08-04 10:33:13.907552+00', '2026-08-04 10:34:24.247883+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1440', 'RC-1440', '193', 'No Regular Review of Follow-Up Performance', 'Operational', 'There''s no periodic check-in to look at how the follow-up process is performing overall.', '0.60', 'external', '2026-08-04 10:33:13.907552+00', '2026-08-04 10:34:24.299886+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1441', 'RC-1441', '193', 'Effective and Ineffective Touches Never Distinguished', 'Strategic', 'Some specific follow-up messages or timings may be working much better than others, but this is never analyzed.', '0.58', 'external', '2026-08-04 10:33:13.907552+00', '2026-08-04 10:34:24.364216+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1444', 'RC-1442', '194', 'No Owner Assigned to Act on Loss-Analysis Findings', 'Operational', 'When a loss reason is identified, nobody is responsible for deciding what to do about it, so the finding sits without an owner to push it into action.', '0.85', 'external', '2026-08-04 12:57:54.606516+00', '2026-08-04 12:59:16.72392+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1445', 'RC-1443', '194', 'Findings Live in Scattered Notes Nobody Revisits', 'Operational', 'Loss reasons get jotted in a CRM field, a notebook, or a chat message, but there is no central place anyone goes back to look at them together.', '0.80', 'external', '2026-08-04 12:57:54.606516+00', '2026-08-04 12:59:16.801694+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1446', 'RC-1444', '194', 'No Regular Review Cadence to Discuss Lost-Deal Patterns', 'Operational', 'There is no recurring meeting or check-in where lost deals and their reasons are actually discussed as a group, so findings never surface into decision-making.', '0.85', 'external', '2026-08-04 12:57:54.606516+00', '2026-08-04 12:59:16.861379+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1447', 'RC-1445', '194', 'Each Loss Treated as a One-Off, Not Connected to a Broader Fix', 'Strategic', 'The founder processes each lost deal individually without stepping back to ask what structural change would prevent the next several losses like it.', '0.75', 'external', '2026-08-04 12:57:54.606516+00', '2026-08-04 12:59:16.916289+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1448', 'RC-1446', '194', 'No Mechanism to Feed Loss Reasons Into Pricing, Positioning, or Product Decisions', 'Strategic', 'Even clear, repeated loss reasons never reach the people or conversations where pricing, messaging, or product roadmap decisions are actually made.', '0.90', 'external', '2026-08-04 12:57:54.606516+00', '2026-08-04 12:59:16.975627+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1449', 'RC-1447', '194', 'Fear of Admitting the Pitch or Product Needs to Change', 'Psychological', 'Acting on a loss reason can mean admitting something core needs to change, which feels threatening, so findings get downplayed or rationalized away instead of acted on.', '0.70', 'external', '2026-08-04 12:57:54.606516+00', '2026-08-04 12:59:17.048713+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1450', 'RC-1448', '194', 'No Tracking of Whether a Fix Actually Reduced That Loss Reason', 'Operational', 'Even on the rare occasion something is changed in response to a loss reason, nobody checks afterward whether that reason actually stopped showing up — so there is no confirmation the fix worked.', '0.75', 'external', '2026-08-04 12:57:54.606516+00', '2026-08-04 12:59:17.107388+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1451', 'RC-1449', '195', 'Won Deals Not Reviewed With the Same Scrutiny as Lost Ones', 'Operational', 'Once a deal closes, the founder moves on — there is no habit of asking why that particular deal worked, so only half the picture (losses) ever gets examined.', '0.85', 'external', '2026-08-04 13:01:34.397909+00', '2026-08-04 13:03:47.327375+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1452', 'RC-1450', '195', 'No Side-by-Side Comparison of Similar Deals With Opposite Outcomes', 'Operational', 'Two deals that looked nearly identical going in — one won, one lost — are never placed next to each other to see what actually diverged.', '0.85', 'external', '2026-08-04 13:01:34.397909+00', '2026-08-04 13:03:47.426801+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1453', 'RC-1451', '195', 'Founder Assumes They Already Know Why Deals Are Won', 'Psychological', 'There is an unexamined confidence about what makes deals succeed, so the assumption is never actually checked against the data.', '0.75', 'external', '2026-08-04 13:01:34.397909+00', '2026-08-04 13:03:47.498749+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1454', 'RC-1452', '195', 'No Comparison of How the Sales Process Itself Differed Between Wins and Losses', 'Operational', 'Whether the same objection was handled differently, or a different number of touchpoints occurred, is never compared across won versus lost deals.', '0.80', 'external', '2026-08-04 13:01:34.397909+00', '2026-08-04 13:03:47.573649+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1455', 'RC-1453', '195', 'Deal Characteristics Not Compared Across Wins and Losses', 'Operational', 'Factors like deal size, lead source, industry, or timeline are never cross-checked between won and lost deals to look for correlations.', '0.80', 'external', '2026-08-04 13:01:34.397909+00', '2026-08-04 13:03:47.644901+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1456', 'RC-1454', '195', 'Suspected Differences Never Verified Against a Larger Sample', 'Strategic', 'Even when a difference between wins and losses is suspected, it stays a hunch — nobody checks it against enough deals to confirm it is real.', '0.75', 'external', '2026-08-04 13:01:34.397909+00', '2026-08-04 13:03:47.722894+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1457', 'RC-1455', '195', 'Survivorship Bias — Only Vivid or Recent Deals Are Remembered', 'Psychological', 'Judgments about why deals are won or lost get shaped by whichever deals are most memorable, not by looking at the full set of outcomes.', '0.70', 'external', '2026-08-04 13:01:34.397909+00', '2026-08-04 13:03:47.787446+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1458', 'RC-1456', '196', '"Lost" Treated as a Single Permanent Status With No Timing Sub-Category', 'Operational', 'Every lost deal gets the same closed-lost label, with no way to flag that some were lost to timing or budget rather than a hard no.', '0.85', 'external', '2026-08-04 13:05:55.452237+00', '2026-08-04 13:06:43.803796+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1459', 'RC-1457', '196', 'No Re-Engagement Timeline Set for Timing-Based Losses', 'Operational', 'Even when a deal is lost because the timing was wrong, no future date is set to circle back, so the prospect just falls off the radar.', '0.85', 'external', '2026-08-04 13:05:55.452237+00', '2026-08-04 13:06:43.873966+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1460', 'RC-1458', '196', 'Lost Prospects Removed From the Pipeline Entirely Rather Than Moved to a Nurture List', 'Operational', 'Once marked lost, a prospect is archived or deleted rather than moved to a separate list meant for future re-approach.', '0.80', 'external', '2026-08-04 13:05:55.452237+00', '2026-08-04 13:06:43.935173+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1461', 'RC-1459', '196', 'No Trigger-Based System to Revisit a Lost Deal When Circumstances Change', 'Operational', 'There is no way to catch signals like a new budget cycle, a funding round, or a leadership change at the prospect''s company that would make it worth reaching out again.', '0.75', 'external', '2026-08-04 13:05:55.452237+00', '2026-08-04 13:06:43.997492+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1462', 'RC-1460', '196', 'Founder Assumes a No Is Final and Avoids Seeming Pushy', 'Psychological', 'Reaching back out to someone who already said no feels uncomfortable or intrusive, so the founder avoids it even when the original reason for the no has likely changed.', '0.75', 'external', '2026-08-04 13:05:55.452237+00', '2026-08-04 13:06:44.050611+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1463', 'RC-1461', '196', 'No Periodic Review of the Lost Pile to Identify Worthwhile Re-Approaches', 'Operational', 'There is no recurring habit of looking back through old lost deals to decide which ones are now worth another attempt.', '0.80', 'external', '2026-08-04 13:05:55.452237+00', '2026-08-04 13:06:44.109258+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1464', 'RC-1462', '196', 'No Tracking of How Often Revisited Lost Deals Actually Convert', 'Strategic', 'Because nobody tracks whether re-approaching old lost deals ever works, the value of doing it stays invisible and the practice never gets prioritized.', '0.70', 'external', '2026-08-04 13:05:55.452237+00', '2026-08-04 13:06:44.16043+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1465', 'RC-1463', '197', 'No Tracking of Which Specific Competitor Won a Lost Deal', 'Operational', 'When a deal is lost to competition, the specific competitor''s name is not recorded anywhere, so there is no way to see patterns over time.', '0.85', 'external', '2026-08-04 13:09:04.541032+00', '2026-08-04 13:09:53.172686+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1466', 'RC-1464', '197', 'No Capture of What the Competitor Offered That Won the Deal', 'Operational', 'Price, features, terms, or relationship factors that tipped the decision toward a competitor are not documented, so the actual reason for the loss stays vague.', '0.85', 'external', '2026-08-04 13:09:04.541032+00', '2026-08-04 13:09:53.233848+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1467', 'RC-1465', '197', 'No Aggregation Across Losses to Spot a Recurring Competitor', 'Operational', 'Even if individual competitor losses are noted, nobody steps back to see whether the same competitor keeps showing up as the reason.', '0.80', 'external', '2026-08-04 13:09:04.541032+00', '2026-08-04 13:09:53.287079+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1468', 'RC-1466', '197', 'Founder Relies on Assumptions About Competitors Rather Than Direct Evidence', 'Psychological', 'Beliefs about what competitors offer or why they win are based on guesswork and general market impressions, not on what actually happened in real lost deals.', '0.70', 'external', '2026-08-04 13:09:04.541032+00', '2026-08-04 13:09:53.350217+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1469', 'RC-1467', '197', 'Competitive Loss Intelligence Not Shared With Anyone Shaping Positioning or Pricing', 'Strategic', 'Even when competitive loss reasons are known, they never reach the person or conversation where pricing or positioning decisions get made.', '0.80', 'external', '2026-08-04 13:09:04.541032+00', '2026-08-04 13:09:53.406706+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1470', 'RC-1468', '197', 'Sales Conversations Don''t Probe for Competitor Details When a Prospect Chooses Someone Else', 'Behavioural', 'When a prospect says they are going with another option, the conversation ends there instead of asking who, what was offered, and why.', '0.80', 'external', '2026-08-04 13:09:04.541032+00', '2026-08-04 13:09:53.460368+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1471', 'RC-1469', '197', 'No Update to Positioning or Battlecards Based on Real Loss Patterns', 'Strategic', 'Even with a clear pattern of losing to a specific competitor for a specific reason, the pitch, messaging, or competitive materials are never revised to address it.', '0.75', 'external', '2026-08-04 13:09:04.541032+00', '2026-08-04 13:09:53.515479+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1472', 'RC-1470', '198', 'Lead Source Not Recorded at the Point of Capture', 'Operational', 'When a new lead comes in, where it came from is not consistently logged, so there is no data to break conversion down by source later.', '0.85', 'external', '2026-08-04 13:14:17.37662+00', '2026-08-04 13:15:06.640036+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1473', 'RC-1471', '198', 'Conversion Rate Calculated in Aggregate Only, Never Segmented by Source', 'Operational', 'Even when overall conversion rate is known, it is never split out by lead source to see which channels actually perform better.', '0.85', 'external', '2026-08-04 13:14:17.37662+00', '2026-08-04 13:15:06.715014+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1474', 'RC-1472', '198', 'No Comparison of Cost-Per-Lead Against Conversion Rate by Source', 'Strategic', 'A cheap source that converts poorly can look efficient on cost alone if nobody weighs cost against how many of those leads actually become customers.', '0.75', 'external', '2026-08-04 13:14:17.37662+00', '2026-08-04 13:15:06.784748+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1475', 'RC-1473', '198', 'Time and Effort Allocated Evenly Across Sources Regardless of Known Quality Differences', 'Operational', 'Sales effort is spread across channels by habit or convenience rather than by which sources are known to convert best.', '0.75', 'external', '2026-08-04 13:14:17.37662+00', '2026-08-04 13:15:06.845491+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1476', 'RC-1474', '198', 'Referral and Cold Leads Treated Identically in the Pipeline', 'Operational', 'Leads with very different starting odds of converting go through the exact same process with no adjustment for the likely difference in intent.', '0.70', 'external', '2026-08-04 13:14:17.37662+00', '2026-08-04 13:15:06.910535+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1477', 'RC-1475', '198', 'No Hypothesis About Which Sources Should Convert Better, So Nothing Gets Tested', 'Strategic', 'There is no working theory about which channels should outperform, so there is nothing specific to confirm or disprove with the data.', '0.70', 'external', '2026-08-04 13:14:17.37662+00', '2026-08-04 13:15:06.984285+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1478', 'RC-1476', '198', 'Underperforming Sources Never Cut Because Nobody Can Prove They Underperform', 'Strategic', 'Without source-level conversion data, a channel that is quietly wasting time or budget keeps getting used because there is no evidence to justify stopping it.', '0.80', 'external', '2026-08-04 13:14:17.37662+00', '2026-08-04 13:15:07.042309+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1479', 'RC-1477', '199', 'No Tracking of How Long Deals Stay in the Pipeline Before Closing or Being Lost', 'Operational', 'The time from first contact to close (or to going cold) is not measured, so there is no visibility into how long the sales process actually takes.', '0.85', 'external', '2026-08-04 13:17:23.486283+00', '2026-08-04 13:18:11.184118+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1480', 'RC-1478', '199', 'No Benchmark for How Long Each Sales Stage Should Normally Take', 'Operational', 'There is no reference point for what a healthy amount of time in each stage looks like, so it is impossible to tell when a deal is taking too long.', '0.80', 'external', '2026-08-04 13:17:23.486283+00', '2026-08-04 13:18:11.251807+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1481', 'RC-1479', '199', 'Stalled Deals Not Flagged or Escalated Once They Exceed a Normal Timeframe', 'Operational', 'A deal that has gone quiet for weeks does not trigger any alert or follow-up action — it just sits until it is eventually forgotten or written off.', '0.85', 'external', '2026-08-04 13:17:23.486283+00', '2026-08-04 13:18:11.309155+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1482', 'RC-1480', '199', 'No Comparison of Cycle Length Between Won Deals and Lost Deals', 'Strategic', 'Whether faster-moving deals tend to close and slower ones tend to die (or vice versa) is never checked, so a potentially useful signal goes unused.', '0.75', 'external', '2026-08-04 13:17:23.486283+00', '2026-08-04 13:18:11.35975+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1483', 'RC-1481', '199', 'Average Sales Cycle Length Allowed to Creep Up Over Time Without Anyone Noticing', 'Operational', 'Deals gradually taking longer to close is a slow, easy-to-miss trend, and without measurement it is never caught until pipeline health is already suffering.', '0.75', 'external', '2026-08-04 13:17:23.486283+00', '2026-08-04 13:18:11.410743+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1484', 'RC-1482', '199', 'No Urgency or Decision Deadlines Built Into the Sales Process Itself', 'Behavioural', 'The sales process does not create any natural point where a prospect needs to decide, so deals can drift indefinitely without a forcing function.', '0.75', 'external', '2026-08-04 13:17:23.486283+00', '2026-08-04 13:18:11.464921+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1485', 'RC-1483', '199', 'Founder Does Not Know Whether a Faster or Slower Cycle Actually Correlates With Winning', 'Knowledge', 'There is no evidence-based understanding of whether speeding up or slowing down the sales process would actually help conversion for this specific business.', '0.70', 'external', '2026-08-04 13:17:23.486283+00', '2026-08-04 13:18:11.515584+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1486', 'RC-1484', '200', 'Conversion Rate Only Calculated as One Blended Average', 'Operational', 'A single conversion number covers every prospect, so it is impossible to tell whether specific segments are pulling the average up or down.', '0.85', 'external', '2026-08-04 13:20:45.948553+00', '2026-08-04 13:22:24.809379+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1487', 'RC-1485', '200', 'Prospect Segment or Deal Size Not Consistently Recorded When a Lead Enters the Pipeline', 'Operational', 'Details like company size, industry, or ICP fit are not captured at intake, so there is no data to segment conversion by later.', '0.80', 'external', '2026-08-04 13:20:45.948553+00', '2026-08-04 13:22:24.881325+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1488', 'RC-1486', '200', 'No Comparison of ICP-Fit Prospects Against Off-ICP Prospects', 'Strategic', 'Prospects who closely match the ideal customer profile are never compared against those who do not, even though their conversion odds likely differ significantly.', '0.80', 'external', '2026-08-04 13:20:45.948553+00', '2026-08-04 13:22:24.943627+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1489', 'RC-1487', '200', 'Founder Assumes All Segments Convert Similarly Without Checking', 'Psychological', 'There is an unexamined assumption that conversion is roughly the same across all types of prospects, so no one bothers to verify it.', '0.70', 'external', '2026-08-04 13:20:45.948553+00', '2026-08-04 13:22:25.007083+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1490', 'RC-1488', '200', 'High-Converting Segments Not Identified or Prioritized for More Focused Effort', 'Strategic', 'Even if a segment quietly converts far better than others, nobody notices to redirect more time and attention toward it.', '0.75', 'external', '2026-08-04 13:20:45.948553+00', '2026-08-04 13:22:25.07397+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1491', 'RC-1489', '200', 'Low-Converting Segments Not Identified or Deprioritized', 'Strategic', 'Segments that rarely convert keep consuming the same sales effort as everything else because there is no evidence flagging them as low-value.', '0.75', 'external', '2026-08-04 13:20:45.948553+00', '2026-08-04 13:22:25.127307+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1492', 'RC-1490', '200', 'Segment Definitions Never Revisited as Understanding of Best-Fit Customer Evolves', 'Strategic', 'Even as the business learns more about who its best customers actually are, the segments used to track conversion are never updated to reflect that.', '0.65', 'external', '2026-08-04 13:20:45.948553+00', '2026-08-04 13:22:25.183268+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1493', 'RC-1491', '201', 'No Record of Which Price or Package Tier Was Offered to Which Prospect', 'Operational', 'What was actually quoted or proposed to each prospect is not logged anywhere, so there is no data to analyze later.', '0.85', 'external', '2026-08-04 13:24:40.032083+00', '2026-08-04 13:25:26.649871+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1494', 'RC-1492', '201', 'No Comparison of Conversion Rate Across Different Pricing or Package Options', 'Operational', 'Even when different offers exist, conversion is never broken down to see which one actually closes more often.', '0.85', 'external', '2026-08-04 13:24:40.032083+00', '2026-08-04 13:25:26.748286+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1495', 'RC-1493', '201', 'Discounts Given Ad Hoc Without Tracking Whether They Increase Conversion', 'Operational', 'Discounts get handed out based on the moment or the prospect''s pushback, with no record of whether they actually changed the outcome.', '0.80', 'external', '2026-08-04 13:24:40.032083+00', '2026-08-04 13:25:26.803513+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1496', 'RC-1494', '201', 'No Test of Full Price Versus Discounted Price to See If the Discount Was Necessary', 'Strategic', 'It is never verified whether the prospect would have said yes at full price anyway, so discounting may be giving away margin for nothing.', '0.75', 'external', '2026-08-04 13:24:40.032083+00', '2026-08-04 13:25:26.870876+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1497', 'RC-1495', '201', 'Package or Tier Chosen at Random or by Founder Preference Rather Than Data', 'Behavioural', 'Which package gets pitched to a given prospect depends on habit or gut feel in the moment, not on evidence of what fits or converts best.', '0.70', 'external', '2026-08-04 13:24:40.032083+00', '2026-08-04 13:25:26.920021+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1498', 'RC-1496', '201', 'No Visibility Into Whether Higher-Priced or Lower-Priced Offers Convert Better', 'Knowledge', 'There is no data-backed answer to whether this specific business converts better leading with a premium offer or a lower-cost entry point.', '0.75', 'external', '2026-08-04 13:24:40.032083+00', '2026-08-04 13:25:26.984281+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1499', 'RC-1497', '201', 'Founder Assumes Price Is the Deciding Factor Without Verifying It', 'Psychological', 'Price gets blamed by default when a deal is lost, without checking whether pricing was actually the reason or just the easiest explanation.', '0.70', 'external', '2026-08-04 13:24:40.032083+00', '2026-08-04 13:25:27.035201+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1500', 'RC-1498', '202', 'No Tracking of What Else a Given Customer Might Need', 'Operational', 'There is no record or ongoing view of a customer''s evolving needs beyond what they originally bought, so expansion opportunities are invisible.', '0.85', 'external', '2026-08-04 13:27:55.489164+00', '2026-08-04 13:28:45.437699+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1501', 'RC-1499', '202', 'Expansion Opportunities Noticed Informally but Never Acted On', 'Behavioural', 'A founder may notice in passing that a customer could use more, but it never turns into an actual offer or conversation.', '0.80', 'external', '2026-08-04 13:27:55.489164+00', '2026-08-04 13:28:45.493411+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1502', 'RC-1500', '202', 'No Process for Identifying Which Customers Are Ready for More', 'Operational', 'There is no way to systematically flag which customers show signs of being ready to expand, so opportunities are found by luck rather than process.', '0.80', 'external', '2026-08-04 13:27:55.489164+00', '2026-08-04 13:28:45.543572+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1503', 'RC-1501', '202', 'Check-Ins With Customers Stay Purely Relationship Maintenance', 'Behavioural', 'Even scheduled customer conversations never include a moment to explore whether more value could be delivered and sold.', '0.75', 'external', '2026-08-04 13:27:55.489164+00', '2026-08-04 13:28:45.726662+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1504', 'RC-1502', '202', 'No Upsell or Cross-Sell Offer Ever Formally Prepared', 'Operational', 'There is nothing specific and ready to pitch to an existing customer — no packaged next step exists to offer even if the moment arises.', '0.80', 'external', '2026-08-04 13:27:55.489164+00', '2026-08-04 13:28:45.776053+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1505', 'RC-1503', '202', 'Founder Feels Awkward Asking an Existing Customer for More Business', 'Psychological', 'Asking someone who already trusts and pays you for more can feel like pushing your luck, so the ask gets avoided even when it is warranted.', '0.70', 'external', '2026-08-04 13:27:55.489164+00', '2026-08-04 13:28:45.824536+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1506', 'RC-1504', '202', 'Expansion Revenue Not Tracked Separately, So It Stays Invisible', 'Operational', 'Revenue from existing customers buying more is not distinguished from new-customer revenue, so there is no way to see whether expansion is happening at all.', '0.75', 'external', '2026-08-04 13:27:55.489164+00', '2026-08-04 13:28:45.872763+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1507', 'RC-1505', '203', 'No System for Logging When a Customer Raises an Issue', 'Operational', 'Complaints or problems raised by customers are not written down anywhere consistent, so they exist only in whoever happened to receive them.', '0.85', 'external', '2026-08-04 13:31:45.161559+00', '2026-08-04 13:32:36.266432+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1508', 'RC-1506', '203', 'No Tracking of How Long Issues Take to Resolve', 'Operational', 'Once a complaint comes in, there is no measurement of the time from report to resolution, so slow or stalled issues go unnoticed.', '0.80', 'external', '2026-08-04 13:31:45.161559+00', '2026-08-04 13:32:36.332587+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1509', 'RC-1507', '203', 'Issue Resolution Depends Entirely on Whoever Happens to Be Available', 'Operational', 'There is no consistent process for handling a complaint — it gets resolved differently depending on who deals with it and how much time they have.', '0.75', 'external', '2026-08-04 13:31:45.161559+00', '2026-08-04 13:32:36.393459+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1510', 'RC-1508', '203', 'No Categorization of Complaint Types, So Recurring Issues Go Unnoticed', 'Operational', 'Complaints are not tagged or grouped by type, so nobody can see that the same issue keeps coming up across different customers.', '0.80', 'external', '2026-08-04 13:31:45.161559+00', '2026-08-04 13:32:36.452626+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1511', 'RC-1509', '203', 'No Follow-Up With the Customer to Confirm the Issue Was Actually Resolved', 'Operational', 'Once something is marked handled internally, there is no check-back with the customer to confirm they are actually satisfied with the outcome.', '0.75', 'external', '2026-08-04 13:31:45.161559+00', '2026-08-04 13:32:36.511347+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1512', 'RC-1510', '203', 'Root Cause of a Recurring Complaint Never Gets Fixed, Only the Symptom', 'Strategic', 'Each instance of a repeating complaint gets patched individually rather than the underlying product, process, or communication issue being addressed.', '0.80', 'external', '2026-08-04 13:31:45.161559+00', '2026-08-04 13:32:36.568589+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1513', 'RC-1511', '203', 'No Escalation Path for Serious or Unresolved Issues', 'Operational', 'When a complaint is too big or sensitive for normal handling, there is no defined way for it to be flagged and handled with more urgency or seniority.', '0.70', 'external', '2026-08-04 13:31:45.161559+00', '2026-08-04 13:32:36.62918+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1514', 'RC-1512', '204', 'No System for Identifying Which Customers Are Satisfied Enough to Ask', 'Operational', 'There is no way to flag which customers are clearly happy and therefore good candidates for a referral or testimonial ask.', '0.80', 'external', '2026-08-04 13:34:36.848326+00', '2026-08-04 13:35:23.650533+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1515', 'RC-1513', '204', 'Referral or Testimonial Ask Never Built Into Any Regular Customer Touchpoint', 'Operational', 'Even during check-ins or positive moments, there is no built-in point where asking for a referral or review naturally happens.', '0.85', 'external', '2026-08-04 13:34:36.848326+00', '2026-08-04 13:35:23.73394+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1516', 'RC-1514', '204', 'Founder Feels Awkward or Transactional Asking a Happy Customer for a Favor', 'Psychological', 'Asking a satisfied customer for something in return feels like it could sour the relationship, so the ask gets avoided.', '0.75', 'external', '2026-08-04 13:34:36.848326+00', '2026-08-04 13:35:23.792528+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1517', 'RC-1515', '204', 'No Easy Way for the Customer to Give a Referral or Testimonial Even If Willing', 'Operational', 'There is no simple template, link, or process ready to hand a willing customer, so even a "yes" turns into friction.', '0.75', 'external', '2026-08-04 13:34:36.848326+00', '2026-08-04 13:35:23.845294+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1518', 'RC-1516', '204', 'Organic Referrals Not Tracked, So Their Volume and Value Stay Invisible', 'Operational', 'When a referral does come in naturally, it is not recorded as such, so there is no visibility into how much of the business actually comes from referrals.', '0.70', 'external', '2026-08-04 13:34:36.848326+00', '2026-08-04 13:35:23.901863+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1519', 'RC-1517', '204', 'No Incentive or Ask Structure to Make Referring Easy or Motivating', 'Strategic', 'There is nothing — even a small thank-you or simple structure — that makes referring feel worthwhile or easy for the customer.', '0.70', 'external', '2026-08-04 13:34:36.848326+00', '2026-08-04 13:35:23.959373+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1520', 'RC-1518', '204', 'Testimonials or Case Studies Never Collected Even When a Customer Would Have Said Yes', 'Operational', 'Positive feedback given informally is never converted into a usable testimonial or case study, so it goes to waste.', '0.70', 'external', '2026-08-04 13:34:36.848326+00', '2026-08-04 13:35:24.017894+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1521', 'RC-1519', '205', 'Renewal or Contract End Dates Not Tracked in One Place', 'Operational', 'There is no single source of truth for when each customer is due to renew, so nothing prompts action ahead of time.', '0.85', 'external', '2026-08-04 13:37:33.052371+00', '2026-08-04 13:38:19.860628+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1522', 'RC-1520', '205', 'No Advance-Notice Outreach Before a Renewal Comes Due', 'Operational', 'Customers are not proactively contacted ahead of their renewal date, so the first conversation about renewal often happens too late.', '0.85', 'external', '2026-08-04 13:37:33.052371+00', '2026-08-04 13:38:19.937906+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1523', 'RC-1521', '205', 'Renewals Only Get Attention When a Customer Cancels or a Payment Fails', 'Operational', 'The renewal process is entirely reactive, triggered only by a customer taking negative action rather than by a proactive checkpoint.', '0.80', 'external', '2026-08-04 13:37:33.052371+00', '2026-08-04 13:38:19.992738+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1524', 'RC-1522', '205', 'No Process for Identifying At-Risk Renewals Ahead of the Renewal Date', 'Operational', 'There is no way to flag which upcoming renewals are likely to be lost, so at-risk accounts get the same treatment as healthy ones until it is too late.', '0.80', 'external', '2026-08-04 13:37:33.052371+00', '2026-08-04 13:38:20.049009+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1525', 'RC-1523', '205', 'No Tracking of Renewal Rate as a Measurable Number', 'Operational', 'What proportion of customers actually renew is never calculated, so there is no baseline to know if renewal performance is good, bad, or changing.', '0.75', 'external', '2026-08-04 13:37:33.052371+00', '2026-08-04 13:38:20.118456+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1526', 'RC-1524', '205', 'Renewal Terms Never Revisited, Just Auto-Continued or Handled Ad Hoc', 'Strategic', 'Price, scope, or terms are not deliberately reviewed at renewal — the contract just rolls over or gets handled inconsistently case by case.', '0.70', 'external', '2026-08-04 13:37:33.052371+00', '2026-08-04 13:38:20.271745+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1527', 'RC-1525', '205', 'No Differentiation in Renewal Approach Between Healthy and At-Risk Accounts', 'Strategic', 'Every renewal gets the same generic treatment regardless of how the relationship is actually going, missing the chance to intervene where it matters most.', '0.75', 'external', '2026-08-04 13:37:33.052371+00', '2026-08-04 13:38:20.329358+00', 'Stage 1→10+', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1528', 'RC-1526', '206', 'Content Calendar Built Independently of Any Marketing Campaign or Business Objective', 'Strategic', 'The calendar gets filled with topics on a schedule, without reference to what the business is actually trying to accomplish that period.', '0.85', 'external', '2026-08-04 13:58:05.279059+00', '2026-08-04 13:58:52.427724+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1529', 'RC-1527', '206', 'No Mapping of Content to Specific Launches, Promotions, or Seasonal Moments', 'Operational', 'Even known upcoming business moments are not deliberately reflected in the content plan ahead of time.', '0.85', 'external', '2026-08-04 13:58:05.279059+00', '2026-08-04 13:58:52.50649+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1530', 'RC-1528', '206', 'Content Topics Chosen Without Reference to That Period''s Business Priorities', 'Strategic', 'What gets posted is decided in isolation from whatever the business is focused on achieving that month or quarter.', '0.80', 'external', '2026-08-04 13:58:05.279059+00', '2026-08-04 13:58:52.566742+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1531', 'RC-1529', '206', 'No One Connects the Content Calendar to the Funnel Stage It Is Meant to Serve', 'Strategic', 'Content is not deliberately mapped to awareness, consideration, or decision-stage purposes, so it is unclear what job any given piece is doing.', '0.75', 'external', '2026-08-04 13:58:05.279059+00', '2026-08-04 13:58:52.62311+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
