insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1579', 'RC-1577', '213', 'No Second Person Ever Reviews Content Before It Goes Out', 'Operational', 'Content is created and published by the same person with no outside eyes ever checking it beforehand.', '0.75', 'external', '2026-08-04 14:58:59.391437+00', '2026-08-04 15:04:02.906193+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
