insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1605', 'RC-1603', '217', 'No Check of What Competitors Are Currently Doing Before Launching', 'Strategic', 'A campaign launches without any scan of whether a competitor is currently running something similar that could compete for the same attention.', '0.80', 'external', '2026-08-04 15:22:03.688961+00', '2026-08-04 15:22:58.301412+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1606', 'RC-1604', '217', 'No Awareness of Broader Market or Industry Timing', 'Knowledge', 'Larger conditions in the market or industry that could affect how the campaign lands are not considered before launch.', '0.75', 'external', '2026-08-04 15:22:03.688961+00', '2026-08-04 15:22:58.385577+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1607', 'RC-1605', '217', 'Campaign Timing Decided by Internal Readiness Alone', 'Operational', 'The launch date is set based purely on when the business is ready, without any check against external timing factors.', '0.80', 'external', '2026-08-04 15:22:03.688961+00', '2026-08-04 15:22:58.444182+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1608', 'RC-1606', '217', 'No Consideration of Audience Attention Cycles', 'Strategic', 'Busy seasons, competing events, or other distractions pulling at the audience''s attention are not factored into launch timing.', '0.75', 'external', '2026-08-04 15:22:03.688961+00', '2026-08-04 15:22:58.506977+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
