insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1610', 'RC-1608', '217', 'No Process for Checking Market Conditions as a Standard Pre-Launch Step', 'Operational', 'There is no habitual check built into the campaign process for scanning external conditions before committing to a launch date.', '0.75', 'external', '2026-08-04 15:22:03.688961+00', '2026-08-04 15:22:58.690504+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1611', 'RC-1609', '217', 'Founder Assumes Timing Does Not Matter Much If the Offer Is Good', 'Psychological', 'There is a belief that a strong offer will succeed regardless of external timing, so timing itself never gets deliberately evaluated.', '0.65', 'external', '2026-08-04 15:22:03.688961+00', '2026-08-04 15:22:58.747764+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1612', 'RC-1610', '218', 'Campaign Spend Not Tracked Precisely Enough to Calculate Cost-Per-Result', 'Operational', 'Total spend on a campaign is not recorded with enough precision to divide it against results and get a meaningful number.', '0.85', 'external', '2026-08-04 15:25:32.15793+00', '2026-08-04 15:26:22.367797+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
