insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1706', 'RC-1704', '231', 'Cost-Cutting Decisions Treat All Expenses the Same', 'Behavioural', 'When costs need to be cut, decisions do not distinguish between costs that are easy to reduce (variable) and those that are locked in regardless (fixed).', '0.75', 'external', '2026-08-05 05:03:19.868565+00', '2026-08-05 05:04:06.171303+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1707', 'RC-1705', '231', 'No Awareness of Which Costs Would Shrink Automatically If Revenue Dropped', 'Knowledge', 'In a downturn, it is unclear which expenses would naturally decrease with lower sales versus which would keep draining cash regardless.', '0.75', 'external', '2026-08-05 05:03:19.868565+00', '2026-08-05 05:04:06.243521+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1708', 'RC-1706', '231', 'Pricing Decisions Made Without Reference to Fixed/Variable Cost Structure', 'Strategic', 'Prices are set without connecting them back to what it actually costs, in fixed and variable terms, to deliver each unit of the product or service.', '0.75', 'external', '2026-08-05 05:03:19.868565+00', '2026-08-05 05:04:06.318072+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1709', 'RC-1707', '231', 'Founder Never Learned the Fixed/Variable Cost Framework as a Concept', 'Knowledge', 'The basic distinction between fixed and variable costs was never taught or picked up, so there is no mental model to apply it with.', '0.70', 'external', '2026-08-05 05:03:19.868565+00', '2026-08-05 05:04:06.393767+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1710', 'RC-1708', '232', 'Profit on the P&L Assumed to Directly Equal Cash in the Bank', 'Knowledge', 'The founder treats the profit figure as if it were the same as available cash, without understanding they can diverge significantly.', '0.85', 'external', '2026-08-05 05:06:46.593202+00', '2026-08-05 05:07:42.074229+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1711', 'RC-1709', '232', 'No Understanding of How Invoiced-But-Unpaid Revenue Affects the Profit-Cash Gap', 'Knowledge', 'Revenue counted as earned on the P&L may not have actually been collected yet, but this distinction is not understood.', '0.85', 'external', '2026-08-05 05:06:46.593202+00', '2026-08-05 05:07:42.151657+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1712', 'RC-1710', '232', 'No Awareness of Non-Cash Items That Affect P&L but Not Cash', 'Knowledge', 'Items like depreciation or accrued expenses show up in the P&L without any actual cash movement, and this is not understood.', '0.75', 'external', '2026-08-05 05:06:46.593202+00', '2026-08-05 05:07:42.217894+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1713', 'RC-1711', '232', 'Confusion When a Profitable Period Still Shows a Cash Shortage', 'Behavioural', 'A profitable-looking P&L alongside a tight bank balance creates confusion rather than being understood as a normal, explainable gap.', '0.80', 'external', '2026-08-05 05:06:46.593202+00', '2026-08-05 05:07:42.285277+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1714', 'RC-1712', '232', 'No Mental Model for Reconciling P&L Profit With Actual Bank Balance', 'Knowledge', 'There is no framework for understanding how the two numbers relate to and differ from each other.', '0.75', 'external', '2026-08-05 05:06:46.593202+00', '2026-08-05 05:07:42.345515+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1715', 'RC-1713', '232', 'Financial Decisions Made Assuming Profit Automatically Means Available Cash to Spend', 'Behavioural', 'Spending decisions get made based on the profit figure, without checking whether that profit has actually turned into spendable cash.', '0.80', 'external', '2026-08-05 05:06:46.593202+00', '2026-08-05 05:07:42.403181+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1716', 'RC-1714', '232', 'Founder Never Had the Accrual-vs-Cash Distinction Explained in Plain Terms', 'Knowledge', 'Nobody has walked through, in simple language, why accounting profit and cash position are two different things.', '0.70', 'external', '2026-08-05 05:06:46.593202+00', '2026-08-05 05:07:42.46125+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1717', 'RC-1715', '233', 'Each P&L Reviewed as a Standalone Snapshot Never Compared to the Prior Period', 'Operational', 'The latest P&L is looked at on its own merits, without placing it next to the previous month to see what changed.', '0.85', 'external', '2026-08-05 05:10:44.31238+00', '2026-08-05 05:11:36.345181+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1718', 'RC-1716', '233', 'No Side-by-Side View of Multiple Months to Spot Trends', 'Operational', 'There is no format or habit of laying several months out together where a trend would become visible.', '0.85', 'external', '2026-08-05 05:10:44.31238+00', '2026-08-05 05:11:36.417798+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1719', 'RC-1717', '233', 'No Tracking of Specific Line Items Over Time', 'Operational', 'Individual cost or revenue lines are not tracked period over period, so a slow creep in either direction goes unnoticed.', '0.80', 'external', '2026-08-05 05:10:44.31238+00', '2026-08-05 05:11:36.475062+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1720', 'RC-1718', '233', 'No Comparison Against Budget or a Prior Forecast', 'Operational', 'Actual results are never checked against what was planned or expected, so there is no sense of variance.', '0.75', 'external', '2026-08-05 05:10:44.31238+00', '2026-08-05 05:11:36.542451+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1721', 'RC-1719', '233', 'Gradual Changes Go Unnoticed Because Only the Latest Number Is Looked At', 'Behavioural', 'Attention goes to the current month''s figure alone, so a slow trend across several months stays invisible.', '0.75', 'external', '2026-08-05 05:10:44.31238+00', '2026-08-05 05:11:36.607692+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1722', 'RC-1720', '233', 'No Trigger to Investigate When a Line Item Changes Significantly', 'Operational', 'Even a sharp period-over-period change in a specific number does not prompt any digging into why.', '0.70', 'external', '2026-08-05 05:10:44.31238+00', '2026-08-05 05:11:36.664787+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1723', 'RC-1721', '233', 'Trends Discovered Late, Only Once They Have Become Impossible to Ignore', 'Strategic', 'By the time a trend is noticed, it has often already become a significant problem rather than an early, manageable signal.', '0.75', 'external', '2026-08-05 05:10:44.31238+00', '2026-08-05 05:11:36.728294+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1724', 'RC-1722', '234', 'No Segmentation of Revenue or Costs by Product, Service, or Stream', 'Operational', 'Financial data is never split out by individual offering, so nothing reveals how each one performs on its own.', '0.85', 'external', '2026-08-05 05:14:03.603139+00', '2026-08-05 05:14:58.938709+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1725', 'RC-1723', '234', 'P&L Only Exists as One Combined Statement for the Whole Business', 'Operational', 'There is no format that presents profitability at anything more granular than the entire business as a single unit.', '0.85', 'external', '2026-08-05 05:14:03.603139+00', '2026-08-05 05:14:59.02559+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1726', 'RC-1724', '234', 'No Way to Tell Which Specific Offering Is Actually Profitable', 'Knowledge', 'Without segmentation, it is impossible to say with confidence whether any single product or service makes or loses money.', '0.80', 'external', '2026-08-05 05:14:03.603139+00', '2026-08-05 05:14:59.096398+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1727', 'RC-1725', '234', 'Costs Not Allocated to the Specific Product or Service That Generated Them', 'Operational', 'Expenses are tracked in aggregate rather than tied back to which offering actually caused them.', '0.75', 'external', '2026-08-05 05:14:03.603139+00', '2026-08-05 05:14:59.150792+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1728', 'RC-1726', '234', 'A Losing Offering Can Be Invisibly Subsidized by a Profitable One', 'Strategic', 'Without a breakdown, a weak product''s losses get absorbed into the overall total, masked by a stronger performer.', '0.75', 'external', '2026-08-05 05:14:03.603139+00', '2026-08-05 05:14:59.203945+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1729', 'RC-1727', '234', 'Grow-or-Cut Decisions Made Without Profitability Data', 'Behavioural', 'Decisions about which offerings to invest in or discontinue get made on instinct rather than on which ones are actually profitable.', '0.75', 'external', '2026-08-05 05:14:03.603139+00', '2026-08-05 05:14:59.263796+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1730', 'RC-1728', '234', 'No Process for Periodically Reviewing Profitability by Revenue Stream', 'Operational', 'Even if a breakdown were done once, there is no recurring habit of revisiting it as the business changes.', '0.70', 'external', '2026-08-05 05:14:03.603139+00', '2026-08-05 05:14:59.322248+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1731', 'RC-1729', '235', 'Budget Allocations Copied From the Prior Period Without Reconsidering Priorities', 'Operational', 'Numbers get carried over from the last budget with minor tweaks rather than being rebuilt around current priorities.', '0.85', 'external', '2026-08-05 05:23:50.953659+00', '2026-08-05 05:24:50.398208+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1732', 'RC-1730', '235', 'No Explicit Link Between Stated Business Goals and Where Budget Is Allocated', 'Strategic', 'Goals are talked about separately from the budget, with nothing tying specific spending decisions back to those goals.', '0.85', 'external', '2026-08-05 05:23:50.953659+00', '2026-08-05 05:24:50.476898+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1733', 'RC-1731', '235', 'Strategic Priorities Identified but Budget Never Adjusted to Reflect Them', 'Operational', 'Even after deciding what matters most, the budget itself is not updated to put more resources behind that priority.', '0.80', 'external', '2026-08-05 05:23:50.953659+00', '2026-08-05 05:24:50.540488+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1734', 'RC-1732', '235', 'Budget Built as One Flat Exercise Rather Than a Prioritization Decision', 'Operational', 'Building the budget is treated as filling in a spreadsheet rather than as a deliberate choice about what matters most.', '0.75', 'external', '2026-08-05 05:23:50.953659+00', '2026-08-05 05:24:50.601463+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1735', 'RC-1733', '235', 'Deprioritized Areas Continue Receiving the Same Budget as Before', 'Operational', 'An area that is no longer a strategic focus keeps getting the same resources it always has, out of habit rather than decision.', '0.75', 'external', '2026-08-05 05:23:50.953659+00', '2026-08-05 05:24:50.659372+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1736', 'RC-1734', '235', 'No Process for Reallocating Budget Toward a New Priority Mid-Period', 'Operational', 'When a new priority emerges during the year, there is no mechanism to shift budget toward it rather than just adding cost on top.', '0.75', 'external', '2026-08-05 05:23:50.953659+00', '2026-08-05 05:24:50.71651+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1737', 'RC-1735', '235', 'Budget Conversations Happen Separately From Strategy Conversations', 'Strategic', 'Discussions about where the business is headed and discussions about spending happen in different rooms, never connected to each other.', '0.70', 'external', '2026-08-05 05:23:50.953659+00', '2026-08-05 05:24:50.773297+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1738', 'RC-1736', '236', 'Budget Built From Desired Spending Without Reference to Expected Revenue', 'Operational', 'Spending gets planned around what feels needed, without checking it against what revenue is actually expected to come in.', '0.85', 'external', '2026-08-05 05:27:30.83058+00', '2026-08-05 05:28:22.772217+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1739', 'RC-1737', '236', 'No Specific Revenue Assumption Stated Alongside the Budget', 'Operational', 'The budget does not come with an explicit revenue number it is assuming, so its own affordability can never really be checked.', '0.85', 'external', '2026-08-05 05:27:30.83058+00', '2026-08-05 05:28:22.936788+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1740', 'RC-1738', '236', 'No Check of Whether the Budget Is Affordable Below Expected Revenue', 'Strategic', 'Nobody stress-tests the budget against a scenario where revenue comes in lower than hoped.', '0.80', 'external', '2026-08-05 05:27:30.83058+00', '2026-08-05 05:28:22.996351+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1741', 'RC-1739', '236', 'Optimistic Revenue Assumptions Used Without Acknowledging the Risk', 'Psychological', 'The budget leans on a best-case revenue number without any acknowledgment that reality could come in lower.', '0.75', 'external', '2026-08-05 05:27:30.83058+00', '2026-08-05 05:28:23.048422+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1742', 'RC-1740', '236', 'No Revised Budget Prepared for a Lower-Revenue Scenario', 'Operational', 'There is no backup version of the budget ready in case revenue underperforms the assumption it was built on.', '0.75', 'external', '2026-08-05 05:27:30.83058+00', '2026-08-05 05:28:23.102129+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1743', 'RC-1741', '236', 'Spending Commitments Made Independent of Revenue Forecast Confidence', 'Behavioural', 'Commitments get made the same way whether the revenue forecast behind them is solid or shaky.', '0.70', 'external', '2026-08-05 05:27:30.83058+00', '2026-08-05 05:28:23.152022+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
