insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1745', 'RC-1743', '237', 'Budget Built Entirely by the Founder Without Consulting Anyone Else', 'Operational', 'Budget numbers come purely from the founder''s own view, with no other perspective factored in.', '0.85', 'external', '2026-08-05 05:30:57.487563+00', '2026-08-05 05:33:28.884424+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
