insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1747', 'RC-1745', '237', 'No Process for Gathering Input Before Finalizing the Budget', 'Operational', 'There is no defined step where input gets collected from others before the budget is locked in.', '0.80', 'external', '2026-08-05 05:30:57.487563+00', '2026-08-05 05:33:29.025388+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1748', 'RC-1746', '237', 'Team Members Find Out About Budget Constraints Only After the Fact', 'Behavioural', 'People learn what they can and cannot spend only once the budget is already set, rather than being part of setting it.', '0.75', 'external', '2026-08-05 05:30:57.487563+00', '2026-08-05 05:33:29.084555+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1749', 'RC-1747', '237', 'No Ownership or Buy-In From Those Responsible for Spending Within an Area', 'Psychological', 'Because the budget was imposed rather than built with them, people feel little personal responsibility for staying within it.', '0.75', 'external', '2026-08-05 05:30:57.487563+00', '2026-08-05 05:33:29.135519+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1750', 'RC-1748', '237', 'Founder Assumes They Know What Each Area Needs Without Checking', 'Psychological', 'There is a confidence that the founder already understands each area''s needs well enough, so nobody else is asked.', '0.70', 'external', '2026-08-05 05:30:57.487563+00', '2026-08-05 05:33:29.185389+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1751', 'RC-1749', '237', 'Budget Inaccuracies From Missing Context Never Caught Early', 'Operational', 'Because nobody else reviews the budget before it is finalized, gaps or unrealistic numbers only surface once problems appear.', '0.70', 'external', '2026-08-05 05:30:57.487563+00', '2026-08-05 05:33:29.235428+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
