insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1753', 'RC-1751', '238', 'Unbudgeted Purchases Made Without Checking Against the Budget First', 'Behavioural', 'Spending decisions happen without anyone pausing to compare the purchase against what is actually left in the relevant budget line.', '0.85', 'external', '2026-08-05 05:36:01.340517+00', '2026-08-05 05:36:52.884538+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
