insert into "root_causes" ("root_cause_id", "root_cause_code", "problem_id", "root_cause_name", "root_cause_category", "explanation", "confidence_weight", "layer", "created_at", "updated_at", "primary_stage_group", "embedding_model", "embedding_version", "embedding_dimension") values ('1755', 'RC-1753', '238', 'Budget Overruns Discovered Only After the Fact', 'Operational', 'Exceeding the budget is noticed by looking back at what was spent, rather than being caught and prevented in the moment.', '0.80', 'external', '2026-08-05 05:36:01.340517+00', '2026-08-05 05:36:53.007213+00', 'Stage 0→1', 'text-embedding-3-small', NULL, '1536') on conflict do nothing;
